#!/usr/bin/env bash
# snell-auto: self-contained Linux Snell v6 installer + environment-aware tuning.
# The distributable is generated by scripts/build-snell-auto.py.
set -Eeuo pipefail
umask 077

auto_tmp=""
auto_cleanup() { if [[ -n "$auto_tmp" && -d "$auto_tmp" ]]; then rm -rf -- "$auto_tmp"; fi; }
trap auto_cleanup EXIT
auto_die() { printf '[snell-auto] 错误：%s\n' "$*" >&2; exit 1; }
auto_log() { printf '[snell-auto] %s\n' "$*"; }

auto_usage() {
  cat <<'USAGE'
Snell v6 一键安装、自适应网络参数与基础安全加固

  sudo bash snell-auto.sh                       安装 Snell、网络优化和基础安全加固
  sudo bash snell-auto.sh install --network off  安装 Snell，不调整网络参数
  sudo bash snell-auto.sh install --no-auto-update 禁用 Snell 自动升级
  sudo bash snell-auto.sh install --security off 不应用安全加固
  bash snell-auto.sh diagnose [--probe IP]       只读检测，可选少量 ICMP 探测
  sudo snell-auto update                        检查并更新 v6
  sudo snell-auto rollback-network              恢复本工具首次优化前的网络参数
  sudo snell-auto security [--no-packages]       单独应用安全加固
  sudo snell-auto security-status               查看安全加固状态和跳过项
  sudo snell-auto rollback-security             回滚本工具的安全配置

安装后：snellx 打开管理菜单，含网络和安全诊断、应用、回滚。
安全加固保留现有 SSH 登录方式和端口；防火墙只审计，不启用或重置。
需要 Linux + glibc + systemd；第三方现有 Snell 安装会停止并提示，不自动迁移。
USAGE
}

auto_check_tool_conflicts() {
  local target
  for target in /usr/local/sbin/snellx /usr/local/bin/snellx; do
    if [[ -e "$target" ]]; then
      grep -Fq '# snellx - interactive manager for the Snell v6 installation created by snell-v6.sh' "$target" ||
        auto_die "${target} 属于其他管理脚本，已停止；请先核对旧安装。"
    fi
  done
  for target in /usr/local/sbin/snell-net /usr/local/sbin/snell-auto /usr/local/sbin/snell-security; do
    if [[ -e "$target" ]]; then
      if [[ "$target" == */snell-auto ]]; then
        grep -Fq '# snell-auto: self-contained Linux Snell v6 installer' "$target" || auto_die "${target} 已存在且不是本工具。"
      elif [[ "$target" == */snell-security ]]; then
        grep -Fq 'Managed by snell-security' "$target" || auto_die "${target} 已存在且不是本工具。"
      else
        grep -Fq 'zzzz-snell-auto-network.conf' "$target" || auto_die "${target} 已存在且不是本工具。"
      fi
    fi
  done
}

auto_install_tool() {
  local source="$1" target="$2" staged
  if [[ -e "$target" ]]; then
    cmp -s "$source" "$target" && return 0
    install -d -m 0700 /var/lib/snell-server/tool-backups
    local backup
    backup="$(mktemp "/var/lib/snell-server/tool-backups/$(basename "$target").XXXXXX")"
    cp -p "$target" "$backup"
  fi
  staged="$(mktemp "${target}.new.XXXXXX")"
  install -o root -g root -m 0755 "$source" "$staged"
  mv -f "$staged" "$target"
}

auto_main() {
  local command="${1:-install}" network=auto security=auto auto_update=preserve arg
  [[ $# -eq 0 ]] || shift
  case "$command" in help|-h|--help) auto_usage; return 0 ;; esac
  [[ "$(uname -s)" == Linux ]] || auto_die "此文件请上传到 Linux VPS 后执行；当前系统不是 Linux。"
  auto_tmp="$(mktemp -d /tmp/snell-auto.XXXXXX)"
  write_installer > "$auto_tmp/snell-manager"
  write_menu > "$auto_tmp/snellx"
  write_network > "$auto_tmp/snell-net"
  write_security > "$auto_tmp/snell-security"
  case "$command" in
    diagnose) bash "$auto_tmp/snell-net" diagnose "$@"; return ;;
    rollback-network)
      [[ $# -eq 0 ]] || auto_die "rollback-network 不接受额外参数。"
      bash "$auto_tmp/snell-net" rollback; return ;;
    security)
      bash "$auto_tmp/snell-security" apply "$@"; return ;;
    security-status)
      bash "$auto_tmp/snell-security" status "$@"; return ;;
    rollback-security)
      bash "$auto_tmp/snell-security" rollback "$@"; return ;;
    update)
      [[ $# -eq 0 ]] || auto_die "update 不接受额外参数。"
      [[ -x /usr/local/sbin/snell-manager ]] || auto_die "请先运行 install。"
      /usr/local/sbin/snell-manager update; return ;;
    install) ;;
    *) auto_die "未知命令：${command}（用 --help 查看用法）" ;;
  esac
  while [[ $# -gt 0 ]]; do
    arg="$1"; shift
    case "$arg" in
      --network)
        [[ $# -gt 0 ]] || auto_die "--network 需要 auto 或 off。"
        network="$1"; shift
        [[ "$network" == auto || "$network" == off ]] || auto_die "--network 需要 auto 或 off。" ;;
      --no-auto-update) auto_update=off ;;
      --security)
        [[ $# -gt 0 ]] || auto_die "--security 需要 auto 或 off。"
        security="$1"; shift
        [[ "$security" == auto || "$security" == off ]] || auto_die "--security 需要 auto 或 off。" ;;
      --auto-update) auto_update=on ;;
      *) auto_die "未知安装选项：${arg}" ;;
    esac
  done
  [[ $EUID -eq 0 ]] || auto_die "请使用 root 或 sudo 运行安装。"
  auto_check_tool_conflicts
  # Complete read-only compatibility/conflict checks before package changes.
  (
    source "$auto_tmp/snell-manager"
    require_root
    require_linux_systemd
    detect_asset_arch >/dev/null
    preflight_existing
  )
  auto_log "环境检测（这是 VPS 侧检测，不代表你本地到 VPS 的速度）："
  bash "$auto_tmp/snell-net" diagnose
  case "$auto_update" in
    off) bash "$auto_tmp/snell-manager" install --no-auto-update ;;
    on) bash "$auto_tmp/snell-manager" install --auto-update ;;
    *) bash "$auto_tmp/snell-manager" install ;;
  esac
  auto_install_tool "$auto_tmp/snellx" /usr/local/sbin/snellx
  # If an older copy of our menu is earlier in PATH, update it too.
  if [[ -e /usr/local/bin/snellx && ! /usr/local/bin/snellx -ef /usr/local/sbin/snellx ]]; then
    auto_install_tool "$auto_tmp/snellx" /usr/local/bin/snellx
  fi
  auto_install_tool "$auto_tmp/snell-net" /usr/local/sbin/snell-net
  auto_install_tool "$auto_tmp/snell-security" /usr/local/sbin/snell-security
  auto_install_tool "${BASH_SOURCE[0]}" /usr/local/sbin/snell-auto
  if [[ "$network" == auto ]]; then
    auto_log "按内核能力和有效内存选择网络参数……"
    if /usr/local/sbin/snell-net apply; then
      if ! /usr/local/sbin/snellx restart; then
        auto_log "优化后 Snell 启动检查失败，正在恢复网络参数。"
        /usr/local/sbin/snell-net rollback || auto_die "网络回滚失败，请查看上方错误。"
        /usr/local/sbin/snellx restart || auto_die "Snell 仍异常，请运行 journalctl -u snell-server。"
        auto_die "网络优化已撤回，Snell 已恢复。"
      fi
    else
      auto_log "网络参数未成功应用；Snell 已安装。可用 snellx diagnose 查看原因。"
      return 1
    fi
  fi
  if [[ "$security" == auto ]]; then
    auto_log "检查并应用基础安全加固……"
    if ! /usr/local/sbin/snell-security apply; then
      auto_log "安全加固未全部完成；Snell 已安装。请用 snellx security-status 查看状态。"
      return 1
    fi
  fi
  /usr/local/sbin/snellx check
  auto_log "安装流程完成。输入 snellx 管理；snellx diagnose 和 security-status 查看实际状态。"
  auto_log "请检查服务商安全组是否放行上面显示的 TCP 端口。"
}

write_installer() {
  cat <<'SNELL_AUTO_INSTALLER_PAYLOAD_END'
#!/usr/bin/env bash
#
# Snell v6 one-click installer and updater
# Source of releases: https://kb.nssurge.com/surge-knowledge-base/release-notes/snell
#
# Usage:
#   sudo bash snell-v6.sh install
#   sudo /usr/local/sbin/snell-manager update
#   sudo /usr/local/sbin/snell-manager show
#

set -Eeuo pipefail
IFS=$'\n\t'
umask 077

readonly RELEASE_PAGE="https://kb.nssurge.com/surge-knowledge-base/release-notes/snell.md"
readonly DOWNLOAD_PREFIX="https://dl.nssurge.com/snell/"
readonly BIN_PATH="/usr/local/bin/snell-server"
readonly MANAGER_PATH="/usr/local/sbin/snell-manager"
readonly CONFIG_DIR="/etc/snell-server"
readonly CONFIG_PATH="${CONFIG_DIR}/snell-server.conf"
readonly STATE_DIR="/var/lib/snell-server"
readonly RELEASE_STATE="${STATE_DIR}/release"
readonly HASH_STATE="${STATE_DIR}/sha256"
readonly PORT_STATE="${STATE_DIR}/port"
readonly FIREWALL_STATE="${STATE_DIR}/firewall"
readonly OWNER_STATE="${STATE_DIR}/managed-by"
readonly SERVICE_UNIT="/etc/systemd/system/snell-server.service"
readonly UPDATE_SERVICE_UNIT="/etc/systemd/system/snell-update.service"
readonly UPDATE_TIMER_UNIT="/etc/systemd/system/snell-update.timer"
readonly SERVICE_NAME="snell-server.service"
readonly TIMER_NAME="snell-update.timer"
readonly LOCK_FILE="/run/lock/snell-manager.lock"
readonly SERVICE_MARKER="Managed by snell-v6.sh"

QUIET=0
TMP_DIR=""
LOCK_HELD=0
AUTO_UPDATE="preserve"

log() {
  if [[ "$QUIET" -eq 0 ]]; then
    printf '[snell] %s\n' "$*"
  fi
}

warn() {
  printf '[snell] 警告：%s\n' "$*" >&2
}

die() {
  printf '[snell] 错误：%s\n' "$*" >&2
  exit 1
}

cleanup() {
  if [[ -n "$TMP_DIR" && -d "$TMP_DIR" ]]; then
    rm -rf -- "$TMP_DIR"
  fi
  if [[ "$LOCK_HELD" -eq 1 ]]; then flock -u 9 || true; fi
}
trap cleanup EXIT

require_root() {
  [[ "${EUID}" -eq 0 ]] || die "请使用 root 运行，例如：sudo bash snell-v6.sh install"
}

require_linux_systemd() {
  [[ "$(uname -s)" == "Linux" ]] || die "仅支持 Linux VPS。"
  command -v systemctl >/dev/null 2>&1 || die "未检测到 systemd，本脚本只支持 systemd 系统。"
  [[ -d /run/systemd/system ]] || die "systemd 当前未作为 init 系统运行。"

  if command -v getconf >/dev/null 2>&1; then
    getconf GNU_LIBC_VERSION >/dev/null 2>&1 ||
      die "官方 Snell 二进制依赖 glibc，不支持 Alpine/musl。请改用 Debian、Ubuntu、RHEL 等 glibc 系统。"
  elif command -v ldd >/dev/null 2>&1 && ldd --version 2>&1 | grep -qi musl; then
    die "官方 Snell 二进制依赖 glibc，不支持 Alpine/musl。请改用 Debian、Ubuntu、RHEL 等 glibc 系统。"
  fi
}

acquire_lock() {
  install -d -m 0755 /run/lock
  exec 9>"$LOCK_FILE"
  flock -n 9 || die "已有安装、升级或配置任务正在运行。"
  LOCK_HELD=1
}

install_dependencies() {
  local missing=0
  local cmd
  for cmd in curl unzip sha256sum awk sed grep od ip ss tc sysctl flock timeout getent useradd groupadd; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
      missing=1
      break
    fi
  done
  if [[ "$missing" -eq 0 ]] && { [[ -s /etc/ssl/certs/ca-certificates.crt ]] || [[ -s /etc/pki/tls/certs/ca-bundle.crt ]] || [[ -s /etc/ssl/ca-bundle.pem ]]; }; then return 0; fi

  log "安装必要依赖……"
  if command -v apt-get >/dev/null 2>&1; then
    export DEBIAN_FRONTEND=noninteractive
    apt-get update -qq
    apt-get install -y -qq curl unzip ca-certificates coreutils gawk iproute2 procps util-linux passwd kmod
  elif command -v dnf >/dev/null 2>&1; then
    dnf install -y curl unzip ca-certificates coreutils gawk iproute procps-ng util-linux shadow-utils kmod
  elif command -v yum >/dev/null 2>&1; then
    yum install -y curl unzip ca-certificates coreutils gawk iproute procps-ng util-linux shadow-utils kmod
  elif command -v pacman >/dev/null 2>&1; then
    pacman -S --noconfirm --needed curl unzip ca-certificates coreutils gawk iproute2 procps-ng util-linux shadow kmod
  elif command -v zypper >/dev/null 2>&1; then
    zypper --non-interactive install curl unzip ca-certificates coreutils gawk iproute2 procps util-linux shadow kmod
  else
    die "无法识别包管理器，请先安装 curl、unzip、ca-certificates、coreutils 和 awk。"
  fi
}

detect_asset_arch() {
  case "$(uname -m)" in
    x86_64|amd64)
      printf 'amd64\n'
      ;;
    i386|i486|i586|i686)
      printf 'i386\n'
      ;;
    aarch64|arm64)
      printf 'aarch64\n'
      ;;
    *)
      die "Snell v6 官方当前不支持该 CPU 架构：$(uname -m)"
      ;;
  esac
}

version_key() {
  local version="${1#v}" rank=3 suffix=0
  [[ "$version" =~ ^6\.([0-9]{1,6})\.([0-9]{1,6})((beta|rc)([0-9]{0,6}))?$ ]] || return 1
  local minor="${BASH_REMATCH[1]}" patch="${BASH_REMATCH[2]}"
  case "${BASH_REMATCH[4]}" in beta) rank=1 ;; rc) rank=2 ;; esac
  suffix="${BASH_REMATCH[5]:-0}"
  printf '6.%06d.%06d.%d.%06d\n' "$((10#$minor))" "$((10#$patch))" "$rank" "$((10#$suffix))"
}

select_release_url() {
  local asset_arch="$1" url tag key
  while IFS= read -r url; do
    tag="${url##*/snell-server-}"; tag="${tag%-linux-*}"
    key="$(version_key "$tag")" || continue
    printf '%s\t%s\n' "$key" "$url"
  done < <(grep -Eo 'https://[^[:space:]"<>`)]+' | grep -E "^https://dl\\.nssurge\\.com/snell/snell-server-v6\\.[0-9]+\\.[0-9]+((beta|rc)[0-9]*)?-linux-${asset_arch}\\.zip$") |
    LC_ALL=C sort -ru | awk 'NR == 1 { print $2 }'
}

fetch_release_url() {
  local asset_arch="$1"
  local page
  local url

  page="$(curl -fsSL \
    --proto '=https' --proto-redir '=https' --tlsv1.2 \
    --retry 3 --retry-delay 2 \
    --connect-timeout 10 --max-time 40 \
    "$RELEASE_PAGE")" || die "无法读取 Snell 官方发布页面。"

  url="$(
    printf '%s\n' "$page" |
      select_release_url "$asset_arch"
  )"

  [[ -n "$url" ]] || die "官方页面未找到适用于 ${asset_arch} 的 Snell v6 下载地址。"
  [[ "$url" == "${DOWNLOAD_PREFIX}"* ]] || die "发布地址未通过域名白名单校验。"
  printf '%s\n' "$url"
}

release_tag_from_url() {
  local url="$1"
  local filename="${url##*/}"
  local tag
  tag="$(printf '%s\n' "$filename" | sed -n 's/^snell-server-\(v6[^-]*\)-linux-.*\.zip$/\1/p')"
  [[ -n "$tag" ]] || die "无法从官方文件名解析版本号。"
  printf '%s\n' "$tag"
}

download_and_verify_binary() {
  local url="$1"
  local expected_arch="$2"
  local archive="${TMP_DIR}/snell.zip"
  local member
  local member_count
  local version_output

  log "下载官方 Snell v6：${url##*/}"
  curl -fsS \
    --proto '=https' --tlsv1.2 \
    --retry 3 --retry-delay 2 \
    --connect-timeout 10 --max-time 180 \
    -o "$archive" "$url" || die "下载 Snell v6 失败。"

  member="$(
    unzip -Z1 "$archive" |
      awk '
        ($0 == "snell-server" || $0 ~ /\/snell-server$/) && !printed {
          print
          printed = 1
        }
      '
  )"
  member_count="$(
    unzip -Z1 "$archive" |
      awk '$0 == "snell-server" || $0 ~ /\/snell-server$/ { count++ } END { print count + 0 }'
  )"
  [[ "$member_count" -eq 1 ]] || die "官方压缩包中的 snell-server 文件数量异常。"
  [[ "$member" != /* && "$member" != *".."* ]] || die "压缩包成员路径不安全。"

  unzip -p "$archive" "$member" > "${TMP_DIR}/snell-server"
  chmod 0755 "${TMP_DIR}/snell-server"

  version_output="$(timeout 10 "${TMP_DIR}/snell-server" --version 2>&1)" ||
    die "下载的 Snell 二进制无法在当前系统执行。"
  printf '%s\n' "$version_output" | grep -Eq 'snell-server v6\.' ||
    die "下载的文件不是 Snell v6 二进制。"

  case "$expected_arch" in
    amd64)
      printf '%s\n' "$version_output" >/dev/null
      ;;
    i386|aarch64)
      printf '%s\n' "$version_output" >/dev/null
      ;;
  esac
}

atomic_install_binary() {
  local source_binary="$1"
  local staged
  install -d -m 0755 "$(dirname "$BIN_PATH")" || return 1
  staged="$(mktemp "${BIN_PATH}.new.XXXXXX")" || return 1
  if ! install -o root -g root -m 0755 "$source_binary" "$staged" || ! mv -f -- "$staged" "$BIN_PATH"; then
    rm -f -- "$staged"
    return 1
  fi
}

record_release_state() {
  local tag="$1"
  local hash="$2"
  install -d -o root -g root -m 0755 "$STATE_DIR"
  printf '%s\n' "$tag" > "$RELEASE_STATE"
  printf '%s\n' "$hash" > "$HASH_STATE"
  chmod 0644 "$RELEASE_STATE" "$HASH_STATE"
}

service_is_managed() {
  [[ -f "$SERVICE_UNIT" ]] && grep -Fq "$SERVICE_MARKER" "$SERVICE_UNIT"
}

preflight_existing() {
  local fragment process unit
  if [[ -e "$MANAGER_PATH" ]]; then
    grep -Fq '# Snell v6 one-click installer and updater' "$MANAGER_PATH" || die "${MANAGER_PATH} 属于其他工具，停止覆盖。"
  fi
  fragment="$(systemctl show "$SERVICE_NAME" -p FragmentPath --value 2>/dev/null || true)"
  if [[ -n "$fragment" || -e "$SERVICE_UNIT" ]]; then
    service_is_managed || die "检测到其他方式安装的 Snell。请先确认其配置/服务路径；本脚本不自动覆盖或迁移。"
    [[ -z "$fragment" || "$fragment" == "$SERVICE_UNIT" ]] || die "Snell 实际服务来自 ${fragment}，停止覆盖。"
  elif [[ -e "$BIN_PATH" || -f "$CONFIG_PATH" ]]; then
    [[ -f "$OWNER_STATE" && "$(<"$OWNER_STATE")" == 'snell-v6.sh' ]] ||
      die "发现未标记归属的 Snell 程序或配置，停止自动覆盖。"
    log "检测到本工具的未完成安装/保留配置，将继续安装并保留端口和 PSK。"
  fi
  for unit in snell.service snell@.service; do
    fragment="$(systemctl show "$unit" -p FragmentPath --value 2>/dev/null || true)"
    [[ -z "$fragment" ]] || die "发现已有 ${unit}（${fragment}），需要先核对旧安装。"
  done
  if [[ -f /etc/snell-server.conf ]] && ! service_is_managed; then
    die "发现旧配置 /etc/snell-server.conf，已停止安装以免生成另一套端口和密钥。"
  fi
  if command -v pgrep >/dev/null 2>&1; then
    process="$(pgrep -x snell-server || true)"
    if [[ -n "$process" ]] && ! service_is_managed; then die "发现非本脚本管理的运行中 Snell（PID ${process}）。"; fi
  fi
}

restart_and_verify_service() {
  local i port
  port="$(port_from_config)" || return 1
  systemctl restart "$SERVICE_NAME" || return 1
  for ((i = 0; i < 5; i++)); do
    sleep 1
    systemctl is-active --quiet "$SERVICE_NAME" || return 1
  done
  service_listening "$port"
}

service_listening() {
  local port="$1" pid
  pid="$(systemctl show "$SERVICE_NAME" -p MainPID --value)" || return 1
  [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1
  ss -H -ltnp | awk -v port="$port" -v pid="$pid" '
    $4 ~ (":" port "$") && index($0, "pid=" pid ",") { found=1 }
    END { exit !found }
  '
}

perform_update() {
  local restart_service="${1:-yes}"
  local asset_arch
  local release_url
  local remote_tag
  local new_hash
  local current_hash=""
  local backup_binary=""
  local current_tag="" remote_key current_key backup_dir

  TMP_DIR="$(mktemp -d /tmp/snell-update.XXXXXX)"
  asset_arch="$(detect_asset_arch)"
  release_url="$(fetch_release_url "$asset_arch")"
  remote_tag="$(release_tag_from_url "$release_url")"
  remote_key="$(version_key "$remote_tag")" || die "无法比较官方版本。"
  if [[ -x "$BIN_PATH" ]]; then
    if [[ -s "$RELEASE_STATE" ]]; then
      current_tag="$(<"$RELEASE_STATE")"
    else
      current_tag="$(timeout 10 "$BIN_PATH" --version 2>&1 | grep -Eo 'v6\.[0-9]+\.[0-9]+((beta|rc)[0-9]*)?' | awk 'NR==1')"
    fi
    current_key="$(version_key "$current_tag")" || die "现有版本无法可靠识别，已停止自动替换。"
    if [[ "$remote_key" < "$current_key" ]]; then
      log "现有版本 ${current_tag} 比官方页面候选 ${remote_tag} 更新，保留当前程序。"
      return 0
    fi
  fi
  download_and_verify_binary "$release_url" "$asset_arch"
  new_hash="$(sha256sum "${TMP_DIR}/snell-server" | awk '{print $1}')"

  if [[ -x "$BIN_PATH" ]]; then
    current_hash="$(sha256sum "$BIN_PATH" | awk '{print $1}')"
  fi

  if [[ -n "$current_hash" && "$current_hash" == "$new_hash" ]]; then
    record_release_state "$remote_tag" "$new_hash"
    log "已是官方当前版本：${remote_tag}"
    return 0
  fi

  if [[ -x "$BIN_PATH" ]]; then
    install -d -m 0700 "${STATE_DIR}/backups"
    backup_dir="$(mktemp -d "${STATE_DIR}/backups/update-$(date +%Y%m%d-%H%M%S).XXXXXX")"
    backup_binary="${backup_dir}/snell-server"
    cp -a -- "$BIN_PATH" "$backup_binary"
    [[ ! -f "$RELEASE_STATE" ]] || cp -a "$RELEASE_STATE" "${backup_dir}/release"
    [[ ! -f "$HASH_STATE" ]] || cp -a "$HASH_STATE" "${backup_dir}/sha256"
    log "旧版本已备份：${backup_dir}"
  fi

  atomic_install_binary "${TMP_DIR}/snell-server" || die "安装新程序失败。"

  if [[ "$restart_service" == "yes" ]] && service_is_managed; then
    if ! restart_and_verify_service; then
      warn "新版本启动失败，正在回滚。"
      if [[ -n "$backup_binary" && -x "$backup_binary" ]]; then
        atomic_install_binary "$backup_binary" || die "恢复旧程序失败：${backup_binary}"
        restart_and_verify_service || die "已恢复旧程序但服务仍异常，请查看 journalctl。"
      fi
      journalctl -u "$SERVICE_NAME" -n 30 --no-pager >&2 || true
      die "升级失败，已尝试恢复旧版本。"
    fi
  fi

  record_release_state "$remote_tag" "$new_hash"
  log "Snell 已升级到官方版本：${remote_tag}"
}

create_service_user() {
  local nologin_shell
  if ! getent group snell >/dev/null 2>&1; then
    groupadd --system snell
  fi
  if ! id -u snell >/dev/null 2>&1; then
    nologin_shell="$(command -v nologin || true)"
    [[ -n "$nologin_shell" ]] || nologin_shell="/usr/sbin/nologin"
    useradd --system \
      --gid snell \
      --home-dir /nonexistent \
      --shell "$nologin_shell" \
      --no-create-home \
      snell
  fi
}

port_in_use() {
  local port="$1"
  local hex_port
  hex_port="$(printf '%04X' "$port")"
  awk -v wanted=":${hex_port}" '
    $2 ~ wanted "$" && $4 == "0A" { found = 1 }
    END { exit(found ? 0 : 1) }
  ' /proc/net/tcp /proc/net/tcp6 2>/dev/null
}

generate_port() {
  local attempt
  local raw
  local port
  for ((attempt = 0; attempt < 200; attempt++)); do
    raw="$(od -An -N2 -tu2 /dev/urandom | tr -d ' ')"
    port=$((10000 + raw % 50001))
    if ! port_in_use "$port"; then
      printf '%s\n' "$port"
      return 0
    fi
  done
  die "尝试 200 次后仍无法找到空闲端口。"
}

generate_psk() {
  od -An -N16 -tx1 /dev/urandom | tr -d ' \n'
  printf '\n'
}

ipv6_available() {
  [[ -s /proc/net/if_inet6 ]] &&
    [[ "$(cat /proc/sys/net/ipv6/conf/all/disable_ipv6 2>/dev/null || printf '1')" == "0" ]] &&
    ip -6 addr show scope global | grep -q 'inet6 ' &&
    [[ -n "$(ip -6 route show default)" ]]
}

config_value() {
  local key="$1"
  awk -v wanted="$key" '
    /^[[:space:]]*[#;]/ { next }
    {
      line = $0
      sub(/^[[:space:]]*/, "", line)
      if (index(line, wanted) == 1) {
        rest = substr(line, length(wanted) + 1)
        if (rest ~ /^[[:space:]]*=/) {
          sub(/^[[:space:]]*=[[:space:]]*/, "", rest)
          sub(/[[:space:]]*$/, "", rest)
          print rest
          exit
        }
      }
    }
  ' "$CONFIG_PATH"
}

port_from_config() {
  local listen_value
  listen_value="$(config_value listen)"
  printf '%s\n' "$listen_value" |
    grep -Eo '([0-9]{1,3}\.){3}[0-9]{1,3}:[0-9]{1,5}|\[[^]]+\]:[0-9]{1,5}' |
    sed -n '1 { s/.*://; p; }'
}

ensure_config() {
  local port
  local psk
  local listen_value

  install -d -o root -g snell -m 0750 "$CONFIG_DIR"
  install -d -o root -g root -m 0755 "$STATE_DIR"

  if [[ -f "$CONFIG_PATH" ]]; then
    psk="$(config_value psk || true)"
    port="$(port_from_config || true)"
    [[ ${#psk} -ge 12 && ${#psk} -le 255 ]] ||
      die "现有配置中的 PSK 长度无效；为避免覆盖密钥，脚本已停止。"
    [[ "$port" =~ ^[0-9]+$ && "$port" -ge 1 && "$port" -le 65535 ]] ||
      die "无法从现有配置中读取监听端口；为避免覆盖配置，脚本已停止。"
    log "保留现有端口和 PSK。"
  else
    port="$(generate_port)"
    psk="$(generate_psk)"
    if ipv6_available; then
      listen_value="0.0.0.0:${port},[::]:${port}"
    else
      listen_value="0.0.0.0:${port}"
    fi

    {
      printf '[snell-server]\n'
      printf 'listen = %s\n' "$listen_value"
      printf 'psk = %s\n' "$psk"
      printf 'mode = default\n'
      printf 'dns-ip-preference = default\n'
    } > "$CONFIG_PATH"
    log "已自动生成空闲端口和 32 字符随机 PSK。"
  fi

  chown root:snell "$CONFIG_PATH"
  chmod 0640 "$CONFIG_PATH"
  printf '%s\n' "$port" > "$PORT_STATE"
  chmod 0644 "$PORT_STATE"
}

write_service_units() {
  if [[ -f "$SERVICE_UNIT" ]] && ! service_is_managed; then
    die "检测到非本脚本管理的 ${SERVICE_UNIT}，为避免覆盖已停止。"
  fi

  {
    printf '# %s\n' "$SERVICE_MARKER"
    cat <<'EOF'
[Unit]
Description=Snell v6 Proxy Server
Documentation=https://kb.nssurge.com/surge-knowledge-base/release-notes/snell
Wants=network-online.target
After=network-online.target

[Service]
Type=simple
User=snell
Group=snell
WorkingDirectory=/var/lib/snell-server
ExecStart=/usr/local/bin/snell-server -c /etc/snell-server/snell-server.conf
Restart=on-failure
RestartSec=3s
LimitNOFILE=1048576
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectKernelLogs=true
ProtectControlGroups=true
ProtectHostname=true
RestrictSUIDSGID=true
LockPersonality=true
MemoryDenyWriteExecute=true
RestrictRealtime=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
SystemCallArchitectures=native
CapabilityBoundingSet=
AmbientCapabilities=

[Install]
WantedBy=multi-user.target
EOF
  } > "$SERVICE_UNIT"

  cat > "$UPDATE_SERVICE_UNIT" <<'EOF'
[Unit]
Description=Check and install official Snell v6 updates
Documentation=https://kb.nssurge.com/surge-knowledge-base/release-notes/snell
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/snell-manager update --quiet
EOF

  cat > "$UPDATE_TIMER_UNIT" <<'EOF'
[Unit]
Description=Daily Snell v6 update check

[Timer]
OnBootSec=15min
OnUnitActiveSec=24h
RandomizedDelaySec=1h
Unit=snell-update.service

[Install]
WantedBy=timers.target
EOF

  chmod 0644 "$SERVICE_UNIT" "$UPDATE_SERVICE_UNIT" "$UPDATE_TIMER_UNIT"
  systemctl daemon-reload
}

install_manager_copy() {
  local source_path="${BASH_SOURCE[0]:-}"
  install -d -m 0755 "$(dirname "$MANAGER_PATH")"

  if [[ -f "$source_path" ]]; then
    if [[ ! "$source_path" -ef "$MANAGER_PATH" ]]; then
      install -o root -g root -m 0755 "$source_path" "$MANAGER_PATH"
    fi
  elif [[ -n "${SNELL_MANAGER_URL:-}" ]]; then
    curl -fsSL \
      --proto '=https' --proto-redir '=https' --tlsv1.2 \
      --retry 3 --connect-timeout 10 --max-time 60 \
      -o "${MANAGER_PATH}.new" "$SNELL_MANAGER_URL"
    chmod 0755 "${MANAGER_PATH}.new"
    mv -f -- "${MANAGER_PATH}.new" "$MANAGER_PATH"
  else
    die "自动升级需要保存管理脚本。请先把脚本下载为文件，再执行：sudo bash snell-v6.sh install"
  fi
}

open_firewall() {
  local port="$1"
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q '^Status: active'; then
    ufw allow "${port}/tcp" comment 'Snell v6' >/dev/null
    printf 'ufw\n' > "$FIREWALL_STATE"
    log "已放行 UFW TCP 端口 ${port}。"
  elif command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
    firewall-cmd --add-port="${port}/tcp" >/dev/null
    firewall-cmd --permanent --add-port="${port}/tcp" >/dev/null
    printf 'firewalld\n' > "$FIREWALL_STATE"
    log "已放行 firewalld TCP 端口 ${port}。"
  else
    printf 'none\n' > "$FIREWALL_STATE"
    warn "未检测到已启用的 UFW/firewalld。若 VPS 有云防火墙/安全组，请手动放行 TCP ${port}。"
  fi
  chmod 0644 "$FIREWALL_STATE"
}

public_ip() {
  local ip=""
  ip="$(curl -4 -fsS --connect-timeout 3 --max-time 6 https://api.ipify.org 2>/dev/null || true)"
  if [[ ! "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
    ip="$(curl -4 -fsS --connect-timeout 3 --max-time 6 https://ifconfig.me/ip 2>/dev/null || true)"
  fi
  if [[ ! "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
    ip="$(curl -6 -fsS --connect-timeout 3 --max-time 6 https://api6.ipify.org 2>/dev/null || true)"
    if [[ ! "$ip" =~ ^[0-9a-fA-F:]+$ || "$ip" != *:* ]]; then ip="<你的VPS公网IP或域名>"; fi
  fi
  printf '%s\n' "$ip"
}

show_connection_info() {
  local port
  local psk
  local mode
  local ip
  local endpoint
  local release="unknown"

  [[ -f "$CONFIG_PATH" ]] || die "尚未安装 Snell 配置。"
  port="$(port_from_config)"
  psk="$(config_value psk)"
  mode="$(config_value mode || true)"
  [[ -n "$mode" ]] || mode="default"
  ip="$(public_ip)"
  endpoint="$ip"
  [[ "$ip" != *:* ]] || endpoint="[$ip]"
  [[ -f "$RELEASE_STATE" ]] && release="$(<"$RELEASE_STATE")"

  cat <<EOF

Snell v6 连接信息
  官方包版本：${release}
  服务器：${ip}
  TCP 端口：${port}
  PSK：${psk}
  模式：${mode}

Surge 配置：
Snell-v6 = snell, ${endpoint}, ${port}, psk=${psk}, version=6, mode=${mode}

服务状态：systemctl status snell-server
实时日志：journalctl -u snell-server -f
升级计时器：systemctl status snell-update.timer
EOF
}

install_snell() {
  local port was_installed=0 timer_enabled=0
  require_root
  require_linux_systemd
  preflight_existing
  install_dependencies
  acquire_lock
  # Recheck under the shared lock before creating an ownership marker.
  preflight_existing

  if [[ -f "$SERVICE_UNIT" ]] && ! service_is_managed; then
    die "检测到非本脚本管理的 ${SERVICE_UNIT}，为避免覆盖已停止。"
  fi
  service_is_managed && was_installed=1
  systemctl is-enabled --quiet "$TIMER_NAME" 2>/dev/null && timer_enabled=1

  install -d -o root -g root -m 0755 "$STATE_DIR"
  printf 'snell-v6.sh\n' > "$OWNER_STATE"
  chmod 0644 "$OWNER_STATE"
  create_service_user
  ensure_config
  install_manager_copy
  if [[ "$was_installed" -eq 1 ]]; then perform_update yes; else perform_update no; fi
  write_service_units

  systemctl enable "$SERVICE_NAME"
  if ! restart_and_verify_service; then
    journalctl -u "$SERVICE_NAME" -n 40 --no-pager >&2 || true
    die "Snell 服务未能启动，请查看上方日志。"
  fi
  case "$AUTO_UPDATE" in
    off) systemctl disable --now "$TIMER_NAME" ;;
    on) systemctl enable --now "$TIMER_NAME" ;;
    preserve)
      if [[ "$was_installed" -eq 0 || "$timer_enabled" -eq 1 ]]; then systemctl enable --now "$TIMER_NAME"; fi ;;
  esac

  port="$(port_from_config)"
  open_firewall "$port"
  log "安装完成；自动更新状态：$(systemctl is-enabled "$TIMER_NAME" 2>/dev/null || true)"
  show_connection_info
}

update_snell() {
  require_root
  require_linux_systemd
  install_dependencies
  acquire_lock
  [[ -f "$CONFIG_PATH" ]] || die "尚未安装，请先运行 install。"
  service_is_managed || die "Snell 服务不是由本脚本管理，拒绝自动覆盖。"
  perform_update yes
}

status_snell() {
  require_root
  local release="unknown"
  [[ -f "$RELEASE_STATE" ]] && release="$(<"$RELEASE_STATE")"
  printf '已记录版本：%s\n' "$release"
  printf '服务状态：%s\n' "$(systemctl is-active "$SERVICE_NAME" 2>/dev/null || true)"
  printf '开机启动：%s\n' "$(systemctl is-enabled "$SERVICE_NAME" 2>/dev/null || true)"
  printf '自动升级：%s\n' "$(systemctl is-active "$TIMER_NAME" 2>/dev/null || true)"
  printf '定时计划：\n'
  systemctl list-timers "$TIMER_NAME" --no-pager 2>/dev/null || true
}

remove_firewall_rule() {
  # We cannot prove ownership of pre-existing rules. Never remove shared rules.
  warn "防火墙放行规则已保留；卸载后可手动删除不再使用的 Snell TCP 规则。"
}

uninstall_snell() {
  local purge="${1:-no}"
  require_root
  require_linux_systemd
  acquire_lock

  systemctl disable --now "$TIMER_NAME" >/dev/null 2>&1 || true
  systemctl disable --now "$SERVICE_NAME" >/dev/null 2>&1 || true
  remove_firewall_rule

  rm -f -- "$SERVICE_UNIT" "$UPDATE_SERVICE_UNIT" "$UPDATE_TIMER_UNIT"
  rm -f -- "$BIN_PATH"
  rm -f -- "$MANAGER_PATH"
  systemctl daemon-reload

  if [[ "$purge" == "yes" ]]; then
    rm -rf -- "$CONFIG_DIR" "$STATE_DIR"
    log "已卸载并清除配置、PSK 与状态数据。"
  else
    log "已卸载；配置和 PSK 保留在 ${CONFIG_DIR}。使用 uninstall --purge 可一并清除。"
  fi
}

usage() {
  cat <<'EOF'
Snell v6 一键管理脚本

用法：
  sudo bash snell-v6.sh install       安装或幂等更新（默认命令）
  sudo snell-manager update           立即检查并安装官方 v6 更新
  sudo snell-manager show             显示 Surge 连接配置（包含 PSK）
  sudo snell-manager status           显示服务与自动升级状态
  sudo snell-manager uninstall        卸载程序，保留配置和 PSK
  sudo snell-manager uninstall --purge 卸载并清除配置、PSK 和状态

选项：
  --quiet   减少普通输出，供 systemd 自动升级使用
  --no-auto-update 安装后禁用自动升级
  --auto-update    安装后启用自动升级（默认保留已有开关，新装启用）
  -h        显示帮助
EOF
}

main() {
  local command="${1:-install}"
  local purge="no"
  [[ $# -gt 0 ]] && shift || true

  while [[ $# -gt 0 ]]; do
    case "$1" in
      --quiet)
        QUIET=1
        ;;
      --purge)
        purge="yes"
        ;;
      --no-auto-update) AUTO_UPDATE="off" ;;
      --auto-update) AUTO_UPDATE="on" ;;
      -h|--help)
        usage
        exit 0
        ;;
      *)
        die "未知参数：$1"
        ;;
    esac
    shift
  done

  case "$command" in
    install)
      install_snell
      ;;
    update)
      update_snell
      ;;
    show)
      require_root
      show_connection_info
      ;;
    status)
      status_snell
      ;;
    uninstall)
      uninstall_snell "$purge"
      ;;
    help|-h|--help)
      usage
      ;;
    *)
      usage
      die "未知命令：$command"
      ;;
  esac
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then main "$@"; fi
SNELL_AUTO_INSTALLER_PAYLOAD_END
}

write_menu() {
  cat <<'SNELL_AUTO_MENU_PAYLOAD_END'
#!/usr/bin/env bash
#
# snellx - interactive manager for the Snell v6 installation created by snell-v6.sh
#
# Install:
#   install -o root -g root -m 0755 snellx /usr/local/sbin/snellx
#
# Usage:
#   snellx
#   snellx status|show|update|restart|psk|port|logs|timer|check

set -Eeuo pipefail
IFS=$'\n\t'
umask 077

readonly CONFIG_PATH="/etc/snell-server/snell-server.conf"
readonly STATE_DIR="/var/lib/snell-server"
readonly PORT_STATE="${STATE_DIR}/port"
readonly RELEASE_STATE="${STATE_DIR}/release"
readonly MANAGER_PATH="/usr/local/sbin/snell-manager"
readonly SERVICE_NAME="snell-server.service"
readonly TIMER_NAME="snell-update.timer"
readonly LOCK_FILE="/run/lock/snell-manager.lock"
readonly NETWORK_TOOL="/usr/local/sbin/snell-net"
readonly SECURITY_TOOL="/usr/local/sbin/snell-security"

LOCK_HELD=0
LAST_BACKUP=""

if [[ -t 1 ]]; then
  readonly C_RESET=$'\033[0m'
  readonly C_BOLD=$'\033[1m'
  readonly C_GREEN=$'\033[32m'
  readonly C_YELLOW=$'\033[33m'
  readonly C_RED=$'\033[31m'
  readonly C_CYAN=$'\033[36m'
else
  readonly C_RESET=""
  readonly C_BOLD=""
  readonly C_GREEN=""
  readonly C_YELLOW=""
  readonly C_RED=""
  readonly C_CYAN=""
fi

info() {
  printf '%s[信息]%s %s\n' "$C_CYAN" "$C_RESET" "$*"
}

ok() {
  printf '%s[成功]%s %s\n' "$C_GREEN" "$C_RESET" "$*"
}

warn() {
  printf '%s[警告]%s %s\n' "$C_YELLOW" "$C_RESET" "$*" >&2
}

die() {
  printf '%s[错误]%s %s\n' "$C_RED" "$C_RESET" "$*" >&2
  exit 1
}

cleanup() {
  if [[ "$LOCK_HELD" -eq 1 ]]; then flock -u 9 || true; fi
}
trap cleanup EXIT

require_root() {
  [[ "$EUID" -eq 0 ]] || die "请使用 root 运行：sudo snellx"
}

require_systemd() {
  command -v systemctl >/dev/null 2>&1 || die "未检测到 systemd。"
  [[ -d /run/systemd/system ]] || die "systemd 当前未作为 init 系统运行。"
}

require_installation() {
  [[ -f "$CONFIG_PATH" ]] || die "未找到配置：${CONFIG_PATH}"
  [[ -x /usr/local/bin/snell-server ]] || die "未找到 Snell 程序：/usr/local/bin/snell-server"
  systemctl cat "$SERVICE_NAME" >/dev/null 2>&1 || die "未找到 ${SERVICE_NAME}。"
}

acquire_lock() {
  install -d -m 0755 /run/lock
  exec 9>"$LOCK_FILE"
  flock -n 9 || die "另一个安装、升级或配置任务正在运行。"
  LOCK_HELD=1
}

release_lock() {
  if [[ "$LOCK_HELD" -eq 1 ]]; then flock -u 9 || true; fi
  LOCK_HELD=0
}

pause_screen() {
  [[ -t 0 ]] || return 0
  printf '\n按 Enter 返回菜单……'
  read -r _unused
}

confirm() {
  local prompt="$1"
  local answer=""
  read -r -p "${prompt} [y/N]: " answer
  [[ "$answer" == "y" || "$answer" == "Y" ]]
}

config_value() {
  local key="$1"
  awk -v wanted="$key" '
    /^[[:space:]]*[#;]/ { next }
    {
      line = $0
      sub(/^[[:space:]]*/, "", line)
      if (index(line, wanted) == 1) {
        rest = substr(line, length(wanted) + 1)
        if (rest ~ /^[[:space:]]*=/) {
          sub(/^[[:space:]]*=[[:space:]]*/, "", rest)
          sub(/[[:space:]]*$/, "", rest)
          print rest
          exit
        }
      }
    }
  ' "$CONFIG_PATH"
}

current_port() {
  local listen_value
  listen_value="$(config_value listen)"
  printf '%s\n' "$listen_value" |
    grep -Eo '([0-9]{1,3}\.){3}[0-9]{1,3}:[0-9]{1,5}|\[[^]]+\]:[0-9]{1,5}' |
    sed -n '1 { s/.*://; p; }'
}

public_ip() {
  local ip=""
  if command -v curl >/dev/null 2>&1; then
    ip="$(curl -4 -fsS --connect-timeout 3 --max-time 6 https://ifconfig.me/ip 2>/dev/null || true)"
  fi
  if [[ ! "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
    ip="<VPS公网IP>"
  fi
  printf '%s\n' "$ip"
}

generate_psk() {
  od -An -N16 -tx1 /dev/urandom | tr -d ' \n'
  printf '\n'
}

port_is_free() {
  local port="$1"
  local listeners
  listeners="$(ss -H -ltn)" || die "无法检查监听端口。"
  ! printf '%s\n' "$listeners" | awk '{ print $4 }' |
    grep -Eq "(^|:|\\])${port}$"
}

port_is_listening() {
  local port="$1" pid
  pid="$(systemctl show "$SERVICE_NAME" -p MainPID --value)" || return 1
  [[ "$pid" =~ ^[1-9][0-9]*$ ]] || return 1
  ss -H -ltnp | awk -v port="$port" -v pid="$pid" '
    $4 ~ (":" port "$") && index($0, "pid=" pid ",") { found=1 }
    END { exit !found }
  '
}

wait_for_port() {
  local port="$1"
  local attempt
  for attempt in $(seq 1 10); do
    if port_is_listening "$port"; then
      return 0
    fi
    sleep 0.2
  done
  return 1
}

generate_port() {
  local port
  local attempt
  for attempt in $(seq 1 200); do
    port="$((20000 + (10#$(od -An -N2 -tu2 /dev/urandom | tr -d ' ') % 40001)))"
    if port_is_free "$port"; then
      printf '%s\n' "$port"
      return 0
    fi
  done
  return 1
}

backup_config() {
  local stamp
  stamp="$(date +%Y%m%d-%H%M%S)"
  LAST_BACKUP="$(mktemp "${CONFIG_PATH}.bak.${stamp}.XXXXXX")" || die "无法创建配置备份。"
  cp -a -- "$CONFIG_PATH" "$LAST_BACKUP" || die "配置备份失败，未修改配置。"
  info "配置已备份：${LAST_BACKUP}"
}

restore_backup() {
  [[ -n "$LAST_BACKUP" && -f "$LAST_BACKUP" ]] || return 1
  cp -a -- "$LAST_BACKUP" "$CONFIG_PATH" || return 1
  chown root:snell "$CONFIG_PATH" || return 1
  chmod 0640 "$CONFIG_PATH" || return 1
}

replace_config_key() {
  local key="$1"
  local value="$2"
  local tmp
  tmp="$(mktemp "${CONFIG_PATH}.tmp.XXXXXX")" || die "无法创建临时配置。"

  awk -v wanted="$key" -v replacement="$value" '
    BEGIN { changed = 0 }
    {
      line = $0
      trimmed = line
      sub(/^[[:space:]]*/, "", trimmed)
      if (!changed && index(trimmed, wanted) == 1) {
        rest = substr(trimmed, length(wanted) + 1)
        if (rest ~ /^[[:space:]]*=/) {
          print wanted " = " replacement
          changed = 1
          next
        }
      }
      print line
    }
    END {
      if (!changed) {
        print wanted " = " replacement
      }
    }
  ' "$CONFIG_PATH" > "$tmp" || die "生成新配置失败，原配置未替换。"

  chown root:snell "$tmp" || die "设置配置所有者失败。"
  chmod 0640 "$tmp" || die "设置配置权限失败。"
  mv -f -- "$tmp" "$CONFIG_PATH" || die "替换配置失败。"
}

replace_listen_port() {
  local old_port="$1"
  local new_port="$2"
  local listen_value
  listen_value="$(config_value listen)"
  [[ -n "$listen_value" ]] || die "无法读取 listen 配置。"

  listen_value="$(
    printf '%s\n' "$listen_value" |
      sed -E "s/:${old_port}([,[:space:]]|$)/:${new_port}\\1/g"
  )"
  replace_config_key "listen" "$listen_value"
}

firewall_backend() {
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q '^Status: active'; then
    printf 'ufw\n'
  elif command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
    printf 'firewalld\n'
  else
    printf 'none\n'
  fi
}

firewall_allow() {
  local port="$1"
  case "$(firewall_backend)" in
    ufw)
      ufw allow "${port}/tcp" comment 'Snell v6' >/dev/null
      ;;
    firewalld)
      firewall-cmd --add-port="${port}/tcp" >/dev/null || return 1
      firewall-cmd --permanent --add-port="${port}/tcp" >/dev/null
      ;;
    none)
      warn "未检测到已启用的 UFW/firewalld，请确认服务商防火墙已放行 TCP ${port}。"
      ;;
  esac
}

firewall_delete() {
  local port="$1"
  case "$(firewall_backend)" in
    ufw)
      ufw --force delete allow "${port}/tcp" >/dev/null 2>&1 || true
      ;;
    firewalld)
      firewall-cmd --remove-port="${port}/tcp" >/dev/null 2>&1 || true
      firewall-cmd --permanent --remove-port="${port}/tcp" >/dev/null 2>&1 || true
      ;;
  esac
}

restart_with_rollback() {
  local description="$1"
  if systemctl restart "$SERVICE_NAME" && sleep 2 && systemctl is-active --quiet "$SERVICE_NAME" && wait_for_port "$(current_port)"; then
    ok "${description}成功，Snell 已正常运行。"
    return 0
  fi

  warn "${description}后服务启动失败，正在恢复上一份配置。"
  restore_backup || die "自动回滚失败，请从备份手动恢复：${LAST_BACKUP}"
  systemctl restart "$SERVICE_NAME" || true
  { systemctl is-active --quiet "$SERVICE_NAME" && wait_for_port "$(current_port)"; } ||
    die "已恢复配置，但服务仍未启动。请运行：journalctl -u ${SERVICE_NAME} -n 80 --no-pager"
  die "新配置不可用，已自动回滚。"
}

show_status() {
  local port
  local release="unknown"
  local service_state
  local timer_state
  port="$(current_port || true)"
  [[ -f "$RELEASE_STATE" ]] && release="$(<"$RELEASE_STATE")"
  service_state="$(systemctl is-active "$SERVICE_NAME" 2>/dev/null || true)"
  timer_state="$(systemctl is-active "$TIMER_NAME" 2>/dev/null || true)"

  printf '%sSnell v6 状态%s\n' "$C_BOLD" "$C_RESET"
  printf '  版本：%s\n' "$release"
  printf '  服务：%s\n' "$service_state"
  printf '  端口：%s\n' "${port:-unknown}"
  printf '  自动升级：%s\n' "$timer_state"
  printf '  配置：%s\n' "$CONFIG_PATH"
  if [[ -n "$port" ]]; then
    printf '  监听：\n'
    ss -ltnp 2>/dev/null | awk -v port="$port" '$4 ~ (":" port "$") { print "    " $0 }'
  fi
}

show_connection() {
  warn "下方包含 PSK，请勿截图或公开转发。"
  if [[ -x "$MANAGER_PATH" ]]; then
    "$MANAGER_PATH" show
    return
  fi

  local ip
  local port
  local psk
  ip="$(public_ip)"
  port="$(current_port)"
  psk="$(config_value psk)"
  printf '服务器：%s\n端口：%s\nPSK：%s\n' "$ip" "$port" "$psk"
  printf 'Surge：Snell-v6 = snell, %s, %s, psk=%s, version=6\n' "$ip" "$port" "$psk"
}

update_snell() {
  local port
  [[ -x "$MANAGER_PATH" ]] || die "未找到 ${MANAGER_PATH}，无法安全更新。"
  info "正在检查官方 Snell v6 更新……"
  "$MANAGER_PATH" update || die "更新失败，查看上方错误。"
  port="$(current_port)"
  systemctl is-active --quiet "$SERVICE_NAME" || die "更新后 Snell 服务未运行。"
  wait_for_port "$port" || die "更新后服务未监听 TCP ${port}。"
  ok "更新检查完成。"
}

restart_snell() {
  local port
  port="$(current_port)"
  acquire_lock
  systemctl restart "$SERVICE_NAME" || die "Snell 重启失败。"
  sleep 2
  systemctl is-active --quiet "$SERVICE_NAME" || die "重启失败，请查看日志。"
  wait_for_port "$port" || die "重启后服务未监听 TCP ${port}。"
  release_lock
  ok "Snell 已重启。"
}

change_psk() {
  local choice=""
  local new_psk=""
  local confirm_psk=""

  printf '\n1) 自动生成安全 PSK\n2) 手动输入 PSK\n0) 取消\n'
  read -r -p "请选择 [1]: " choice
  choice="${choice:-1}"
  case "$choice" in
    1)
      new_psk="$(generate_psk)"
      ;;
    2)
      read -r -s -p "输入新 PSK（12–255 位字母、数字或 ._~+-）: " new_psk
      printf '\n'
      read -r -s -p "再次输入新 PSK: " confirm_psk
      printf '\n'
      [[ "$new_psk" == "$confirm_psk" ]] || die "两次输入不一致。"
      ;;
    0)
      info "已取消。"
      return 0
      ;;
    *)
      die "无效选择。"
      ;;
  esac

  [[ ${#new_psk} -ge 12 && ${#new_psk} -le 255 ]] || die "PSK 长度必须为 12–255 字符。"
  [[ "$new_psk" =~ ^[A-Za-z0-9._~+-]+$ ]] ||
    die "PSK 只能包含字母、数字或 . _ ~ + -。"

  warn "修改 PSK 后，所有客户端都必须同步更新。"
  confirm "确认修改 PSK？" || {
    info "已取消。"
    return 0
  }

  acquire_lock
  backup_config
  replace_config_key "psk" "$new_psk"
  restart_with_rollback "修改 PSK"
  release_lock
  show_connection
}

change_port() {
  local old_port
  local new_port=""
  local backend
  old_port="$(current_port)"

  read -r -p "输入新端口（留空自动生成，当前 ${old_port}）: " new_port
  if [[ -z "$new_port" ]]; then
    new_port="$(generate_port)" || die "无法自动找到空闲端口。"
    info "已选择空闲端口：${new_port}"
  fi

  [[ "$new_port" =~ ^[0-9]+$ ]] || die "端口必须是数字。"
  (( new_port >= 1024 && new_port <= 65535 )) || die "端口范围必须是 1024–65535。"
  [[ "$new_port" != "$old_port" ]] || {
    info "新旧端口相同，无需修改。"
    return 0
  }
  port_is_free "$new_port" || die "端口 ${new_port} 已被占用。"

  warn "修改端口后，所有客户端和服务商防火墙都必须同步更新。"
  confirm "确认把端口从 ${old_port} 改为 ${new_port}？" || {
    info "已取消。"
    return 0
  }

  acquire_lock
  backup_config
  backend="$(firewall_backend)"
  firewall_allow "$new_port" || die "防火墙放行失败，未修改 Snell 配置。"
  replace_listen_port "$old_port" "$new_port"

  if ! systemctl restart "$SERVICE_NAME" ||
    ! systemctl is-active --quiet "$SERVICE_NAME" ||
    ! wait_for_port "$new_port"; then
    warn "新端口启动失败，正在回滚。"
    restore_backup || die "自动回滚失败，请从备份恢复：${LAST_BACKUP}"
    systemctl restart "$SERVICE_NAME" || true
    [[ "$backend" == "none" ]] || warn "新端口防火墙规则已保留，请确认是否需要手动删除。"
    die "端口修改失败，已恢复旧配置。"
  fi

  install -d -o root -g root -m 0755 "$STATE_DIR"
  printf '%s\n' "$new_port" > "$PORT_STATE"
  chmod 0644 "$PORT_STATE"
  # Keep the old allow rule: it may predate this tool or be shared by another service.
  [[ "$backend" == "none" ]] || warn "旧端口的放行规则已保留，确认无其他用途后可手动删除。"
  release_lock
  ok "端口已从 ${old_port} 修改为 ${new_port}。"
  show_connection
}

show_logs() {
  journalctl -u "$SERVICE_NAME" -n 80 --no-pager
}

toggle_timer() {
  acquire_lock
  if systemctl is-active --quiet "$TIMER_NAME"; then
    warn "自动升级当前已启用。"
    confirm "确认关闭每日自动升级检查？" || {
      info "已取消。"
      release_lock
      return 0
    }
    systemctl disable --now "$TIMER_NAME" || die "关闭自动升级失败。"
    ok "自动升级已关闭。"
  else
    systemctl enable --now "$TIMER_NAME" || die "开启自动升级失败。"
    ok "自动升级已启用。"
    systemctl list-timers "$TIMER_NAME" --no-pager || true
  fi
  release_lock
}

network_command() {
  [[ -x "$NETWORK_TOOL" ]] || die "未安装网络模块，请先运行 snell-auto.sh。"
  "$NETWORK_TOOL" "$@"
}

optimize_network() {
  network_command apply || return 1
  info "网络参数已检查。已有连接可能继续使用旧参数；新连接生效，必要时选择重启 Snell。"
}

security_command() {
  [[ -x "$SECURITY_TOOL" ]] || die "未安装安全模块，请重新运行新版 snell-auto.sh。"
  "$SECURITY_TOOL" "$@"
}

health_check() {
  local port
  local failed=0
  port="$(current_port || true)"

  printf '%sSnell v6 健康检查%s\n' "$C_BOLD" "$C_RESET"
  if systemctl is-active --quiet "$SERVICE_NAME"; then
    ok "服务运行中"
  else
    warn "服务未运行"
    failed=1
  fi

  if [[ -n "$port" ]] && port_is_listening "$port"; then
    ok "TCP ${port} 正在监听"
  else
    warn "未检测到 Snell 监听端口"
    failed=1
  fi

  if systemctl is-active --quiet "$TIMER_NAME"; then
    ok "自动升级定时器运行中"
  else
    warn "自动升级定时器未运行"
  fi

  if command -v ufw >/dev/null 2>&1 && ufw status | grep -q '^Status: active'; then
    if ufw status | grep -Eq "^${port}/tcp[[:space:]]+ALLOW"; then
      ok "UFW 已放行 TCP ${port}"
    else
      warn "UFW 未发现 TCP ${port} 放行规则"
      failed=1
    fi
  fi

  if [[ "$failed" -eq 0 ]]; then
    ok "检查通过。"
  else
    return 1
  fi
}

print_menu() {
  clear 2>/dev/null || true
  printf '%s\n' "${C_BOLD}Snell v6 管理工具（snellx）${C_RESET}"
  printf '%s\n' "──────────────────────────────"
  printf '  1) 查看运行状态\n'
  printf '  2) 查看连接配置（含 PSK）\n'
  printf '  3) 检查并更新 Snell\n'
  printf '  4) 重启 Snell\n'
  printf '  5) 修改/随机生成 PSK\n'
  printf '  6) 修改/随机生成端口\n'
  printf '  7) 查看最近日志\n'
  printf '  8) 开启/关闭自动升级\n'
  printf '  9) 一键健康检查\n'
  printf '  10) 检测系统与网络环境\n'
  printf '  11) 应用自适应网络参数\n'
  printf '  12) 回滚本工具的网络参数\n'
  printf '  13) 查看安全加固状态\n'
  printf '  14) 应用基础安全加固\n'
  printf '  15) 回滚本工具的安全配置\n'
  printf '  0) 退出\n'
  printf '%s\n' "──────────────────────────────"
}

interactive_menu() {
  local choice
  while true; do
    print_menu
    read -r -p "请选择 [0-15]: " choice || return 0
    printf '\n'
    case "$choice" in
      1) show_status || true ;;
      2) show_connection || true ;;
      3) update_snell || true ;;
      4) restart_snell || true ;;
      5) change_psk || true ;;
      6) change_port || true ;;
      7) show_logs || true ;;
      8) toggle_timer || true ;;
      9) health_check || true ;;
      10) network_command diagnose || true ;;
      11) optimize_network || true ;;
      12) network_command rollback || true ;;
      13) security_command status || true ;;
      14) security_command apply || true ;;
      15) security_command rollback || true ;;
      0) printf '再见。\n'; return 0 ;;
      *) warn "无效选择：${choice}" ;;
    esac
    pause_screen
  done
}

usage() {
  cat <<'EOF'
用法：
  snellx                 打开交互式菜单
  snellx status          查看状态
  snellx show            显示连接配置（包含 PSK）
  snellx update          检查并更新 Snell
  snellx restart         重启服务
  snellx psk             修改/生成 PSK
  snellx port            修改/生成端口
  snellx logs            查看最近日志
  snellx timer           开启/关闭自动升级
  snellx check           一键健康检查
  snellx diagnose        检测系统/网络（可追加 --probe IP）
  snellx optimize        应用保守的自适应网络参数
  snellx rollback-network 恢复本工具首次优化前的参数
  snellx security [--no-packages] 应用基础安全加固
  snellx security-status 查看安全加固状态
  snellx rollback-security 回滚本工具的安全配置
EOF
}

main() {
  require_root
  require_systemd
  require_installation

  case "${1:-menu}" in
    menu) interactive_menu ;;
    status) show_status ;;
    show) show_connection ;;
    update) update_snell ;;
    restart) restart_snell ;;
    psk) change_psk ;;
    port) change_port ;;
    logs) show_logs ;;
    timer) toggle_timer ;;
    check) health_check ;;
    diagnose) shift; network_command diagnose "$@" ;;
    optimize) optimize_network ;;
    rollback-network) network_command rollback ;;
    security) shift; security_command apply "$@" ;;
    security-status) shift; security_command status "$@" ;;
    rollback-security) shift; security_command rollback "$@" ;;
    -h|--help|help) usage ;;
    *) usage; exit 2 ;;
  esac
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then main "$@"; fi
SNELL_AUTO_MENU_PAYLOAD_END
}

write_network() {
  cat <<'SNELL_AUTO_NETWORK_PAYLOAD_END'
#!/usr/bin/env bash
# Conservative, reversible network defaults for a Linux Snell VPS.
# Source this file to test functions; only direct execution runs main.

SNELL_NET_STATE_DIR=${SNELL_NET_STATE_DIR:-/var/lib/snell-net}
SNELL_NET_CONFIG=${SNELL_NET_CONFIG:-/etc/sysctl.d/zzzz-snell-auto-network.conf}
SNELL_NET_PROC=${SNELL_NET_PROC:-/proc}
SNELL_NET_CGROUP=${SNELL_NET_CGROUP:-/sys/fs/cgroup}
SNELL_NET_MARKER='# Managed by snell-net; use snell-net rollback to restore the first backup.'
SNELL_NET_PENDING=0
SNELL_NET_MEMORY_BYTES=0
SNELL_NET_MEMORY_SOURCE=unknown
SNELL_NET_ENVIRONMENT=unknown
SNELL_NET_CAN_APPLY=0
SNELL_NET_REASON='尚未检测'

net_log() { printf '[snell-net] %s\n' "$*"; }
net_warn() { printf '[snell-net] %s\n' "$*" >&2; }
net_read() { sysctl -n "$1" 2>/dev/null | awk '{$1=$1; print}'; }
net_write() { sysctl -q -w "$1=$2" >/dev/null 2>&1; }
net_positive_integer() { [[ "$1" =~ ^[0-9]+$ && ${#1} -le 18 && "$1" != 0 ]]; }

net_supported_key() {
  case "$1" in
    net.ipv4.tcp_congestion_control|net.core.default_qdisc|net.ipv4.tcp_mtu_probing|net.ipv4.tcp_moderate_rcvbuf|net.core.rmem_max|net.core.wmem_max|net.ipv4.tcp_rmem|net.ipv4.tcp_wmem) return 0 ;;
    *) return 1 ;;
  esac
}

net_detect_environment() {
  local container rc vm mapped cap
  SNELL_NET_CAN_APPLY=0
  SNELL_NET_ENVIRONMENT=unknown
  if [[ "$(uname -s)" != Linux ]]; then
    SNELL_NET_REASON='非 Linux 系统，仅提供信息'; return 0
  fi
  if [[ -e /.dockerenv || -e /run/.containerenv || -s /run/systemd/container ]]; then
    SNELL_NET_ENVIRONMENT=container
    SNELL_NET_REASON='检测到容器，跳过可能影响共享内核的 sysctl'; return 0
  fi
  if ! command -v systemd-detect-virt >/dev/null 2>&1; then
    SNELL_NET_REASON='缺少 systemd-detect-virt，无法可靠确认虚拟化边界'; return 0
  fi
  container=$(systemd-detect-virt --container 2>/dev/null); rc=$?
  if [[ "$rc" -eq 0 ]]; then
    SNELL_NET_ENVIRONMENT="container:$container"
    SNELL_NET_REASON='检测到容器/受限环境，跳过 sysctl'; return 0
  elif [[ "$rc" -ne 1 ]]; then
    SNELL_NET_REASON='容器检测失败，不能确认宿主权限'; return 0
  fi
  mapped=$(awk 'NF==3 {print $1 " " $2 " " $3}' "$SNELL_NET_PROC/self/uid_map" 2>/dev/null)
  if [[ "$mapped" != '0 0 4294967295' ]]; then
    SNELL_NET_REASON='用户命名空间不明确或受到限制'; return 0
  fi
  cap=$(awk '/^CapEff:/ {print $2}' "$SNELL_NET_PROC/self/status" 2>/dev/null)
  if [[ ! "$cap" =~ ^[0-9a-fA-F]{1,16}$ ]]; then
    SNELL_NET_REASON='无法读取有效内核权限'; return 0
  fi
  # CAP_NET_ADMIN (bit 12) is needed to change the network namespace defaults.
  if (( (16#$cap & 4096) == 0 )); then
    SNELL_NET_REASON='缺少 CAP_NET_ADMIN，跳过 sysctl'; return 0
  fi
  vm=$(systemd-detect-virt --vm 2>/dev/null); rc=$?
  if [[ "$rc" -eq 0 && -n "$vm" ]]; then
    SNELL_NET_ENVIRONMENT="vm:$vm"
  elif [[ "$rc" -eq 1 ]]; then
    SNELL_NET_ENVIRONMENT=bare-metal
  else
    SNELL_NET_REASON='虚拟机检测失败，无法确认内核控制权限'; return 0
  fi
  SNELL_NET_CAN_APPLY=1
  SNELL_NET_REASON='独立内核环境且具备网络管理权限'
}

net_consider_memory_limit() {
  local path=$1 limit
  [[ -r "$path" ]] || return 0
  read -r limit < "$path" || return 0
  if net_positive_integer "$limit" && (( limit < SNELL_NET_MEMORY_BYTES )); then
    SNELL_NET_MEMORY_BYTES=$limit
    SNELL_NET_MEMORY_SOURCE="cgroup:$path"
  fi
}

net_cgroup_memory_limits() {
  local hierarchy controllers relative root mountpoint kind suffix current limitfile
  [[ -r "$SNELL_NET_PROC/self/cgroup" && -r "$SNELL_NET_PROC/self/mountinfo" ]] || return 0
  while IFS=: read -r hierarchy controllers relative; do
    if [[ "$hierarchy" == 0 && -z "$controllers" ]]; then
      kind=cgroup2; limitfile=memory.max
    elif [[ ",$controllers," == *,memory,* ]]; then
      kind=cgroup; limitfile=memory.limit_in_bytes
    else
      continue
    fi
    while IFS=$'\t' read -r root mountpoint; do
      # Kernel mountinfo uses octal escapes. Decode only the path fields.
      printf -v root '%b' "$root"
      printf -v mountpoint '%b' "$mountpoint"
      [[ "$relative" == /* && "$root" == /* && "$mountpoint" == /* ]] || continue
      # Reject traversal rather than accidentally examining an unrelated path.
      [[ "/$relative/" != */../* ]] || continue
      if [[ "$root" == / ]]; then
        suffix=$relative
      elif [[ "$relative" == "$root" ]]; then
        suffix=''
      elif [[ "$relative" == "$root/"* ]]; then
        suffix=${relative#"$root"}
      else
        # Namespaced cgroups may report / relative to a non-/ mounted root.
        [[ "$relative" == / ]] || continue
        suffix=''
      fi
      current="${mountpoint%/}$suffix"
      current=${current%/}
      [[ -n "$current" ]] || current=/
      while [[ "$current" == "$mountpoint" || "$current" == "$mountpoint/"* ]]; do
        net_consider_memory_limit "$current/$limitfile"
        [[ "$current" != "$mountpoint" ]] || break
        current=${current%/*}
      done
    done < <(awk -v wanted="$kind" '
      {split($0, parts, " - "); split(parts[2], tail, " ")}
      tail[1]==wanted && (wanted=="cgroup2" || tail[3] ~ /(^|,)memory(,|$)/) {print $4 "\t" $5}
    ' "$SNELL_NET_PROC/self/mountinfo")
  done < "$SNELL_NET_PROC/self/cgroup"
}

net_detect_memory() {
  local kib
  kib=$(awk '/^MemTotal:/ {print $2; exit}' "$SNELL_NET_PROC/meminfo" 2>/dev/null)
  if ! net_positive_integer "${kib:-0}"; then
    SNELL_NET_MEMORY_BYTES=0; SNELL_NET_MEMORY_SOURCE=unknown; return 1
  fi
  SNELL_NET_MEMORY_BYTES=$((kib * 1024))
  SNELL_NET_MEMORY_SOURCE=MemTotal
  net_consider_memory_limit "$SNELL_NET_CGROUP/memory.max"
  net_consider_memory_limit "$SNELL_NET_CGROUP/memory/memory.limit_in_bytes"
  net_cgroup_memory_limits
}

net_buffer_target() {
  local bytes=$1
  if (( bytes <= 536870912 )); then printf '4194304\n'
  elif (( bytes <= 1073741824 )); then printf '8388608\n'
  elif (( bytes <= 2147483648 )); then printf '16777216\n'
  else printf '33554432\n'; fi
}

net_show_value() {
  local value
  value=$(net_read "$1") || value='不支持/不可读取'
  printf '  %s = %s\n' "$1" "${value:-不支持/不可读取}"
}

net_diagnose() {
  local name probe=${1:-} key
  net_detect_environment
  name=$(awk -F= '$1=="PRETTY_NAME" {sub(/^[^=]*=/, ""); gsub(/^"|"$/, ""); print; exit}' /etc/os-release 2>/dev/null)
  net_log "系统：${name:-未知} | $(uname -srm)"
  net_log "虚拟化：${SNELL_NET_ENVIRONMENT}；$SNELL_NET_REASON"
  if net_detect_memory; then
    net_log "有效内存上限：$((SNELL_NET_MEMORY_BYTES / 1048576)) MiB（${SNELL_NET_MEMORY_SOURCE}）"
    net_log "缓冲上限建议：$(( $(net_buffer_target "$SNELL_NET_MEMORY_BYTES") / 1048576 )) MiB；保留现有更大值"
  else
    net_warn '无法读取有效内存，不会自动设置缓冲参数'
  fi
  if command -v ip >/dev/null 2>&1; then
    net_log '默认 IPv4 路由：'; ip -4 route show default 2>/dev/null || true
    net_log '默认 IPv6 路由：'; ip -6 route show default 2>/dev/null || true
    net_log '网卡与当前 MTU：'; ip -o link show 2>/dev/null || true
  else
    net_warn '缺少 ip，无法显示路由与 MTU'
  fi
  net_log '实际正在使用的队列（不会替换）：'
  if command -v tc >/dev/null 2>&1; then tc qdisc show 2>/dev/null || true
  else net_warn '缺少 tc，无法读取当前队列'; fi
  for key in net.core.default_qdisc net.ipv4.tcp_available_congestion_control net.ipv4.tcp_congestion_control net.ipv4.tcp_mtu_probing net.ipv4.tcp_moderate_rcvbuf net.core.rmem_max net.core.wmem_max net.ipv4.tcp_rmem net.ipv4.tcp_wmem; do
    net_show_value "$key"
  done
  net_log 'default_qdisc 是新队列的默认值，不代表网卡实际已使用 fq；现有 TCP 连接也不一定采用新拥塞算法。'
  [[ -z "$probe" ]] || net_probe "$probe"
}

net_valid_ip() {
  local octet part
  if [[ "$1" == *:* ]]; then
    [[ "$1" =~ ^[0-9a-fA-F:]+$ && ${#1} -le 39 ]]
    return
  fi
  [[ "$1" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
  local IFS=.
  for part in $1; do
    [[ ${#part} -le 3 ]] || return 1
    octet=$((10#$part)); (( octet <= 255 )) || return 1
  done
}

net_probe() {
  local target=$1
  net_valid_ip "$target" || { net_warn '--probe 仅接受 IPv4/IPv6 地址'; return 1; }
  command -v ping >/dev/null 2>&1 || { net_warn '没有 ping，跳过可选探测'; return 0; }
  net_log "低流量探测 ${target}：4 个 ICMP 包，最多 10 秒。这里只反映 VPS 到该 IP 的路径。"
  if [[ "$target" == *:* ]]; then ping -6 -n -c 4 -W 2 -w 10 "$target" || true
  else ping -4 -n -c 4 -W 2 -w 10 "$target" || true; fi
  net_log 'ICMP 可能被限速/屏蔽；该结果不等同于客户端到 VPS 的吞吐量，也不用于自动调参。'
}

net_plan() {
  local desired_file=$1 previous_file=$2 target key current desired available a b c
  target=$(net_buffer_target "$SNELL_NET_MEMORY_BYTES")
  : > "$desired_file" || return 1
  : > "$previous_file" || return 1
  for key in net.ipv4.tcp_congestion_control net.core.default_qdisc net.ipv4.tcp_mtu_probing net.ipv4.tcp_moderate_rcvbuf net.core.rmem_max net.core.wmem_max net.ipv4.tcp_rmem net.ipv4.tcp_wmem; do
    current=$(net_read "$key") || continue
    [[ -n "$current" ]] || continue
    if [[ -f "$SNELL_NET_STATE_DIR/baseline/values" ]] && ! awk -F '\t' -v key="$key" '$1==key {found=1} END {exit !found}' "$SNELL_NET_STATE_DIR/baseline/values"; then
      net_warn "$key 在首次备份中不存在，保留当前值；先 rollback 后重新 apply 可纳入管理"
      continue
    fi
    desired=$current
    case "$key" in
      net.ipv4.tcp_congestion_control)
        case "$current" in
          bbr|bbr2|bbr3) ;;
          *)
            available=$(net_read net.ipv4.tcp_available_congestion_control) || available=''
            if [[ " $available " != *' bbr '* ]] && command -v modprobe >/dev/null 2>&1; then
              modprobe tcp_bbr >/dev/null 2>&1 || true
              available=$(net_read net.ipv4.tcp_available_congestion_control) || available=''
            fi
            if [[ " $available " == *' bbr '* ]]; then desired=bbr
            else net_log "BBR 不可用，保留拥塞算法 $current"; fi
            ;;
        esac ;;
      net.core.default_qdisc)
        case "$current" in fq|fq_codel|cake) ;; *) desired=fq ;; esac ;;
      net.ipv4.tcp_mtu_probing)
        [[ "$current" =~ ^[012]$ ]] || return 1
        [[ "$current" == 2 ]] || desired=1 ;;
      net.ipv4.tcp_moderate_rcvbuf) desired=1 ;;
      net.core.rmem_max|net.core.wmem_max)
        net_positive_integer "$current" || return 1
        if (( current < target )); then desired=$target
        elif (( current > target )); then net_log "$key 已高于建议上限，保留 $current"; fi ;;
      net.ipv4.tcp_rmem|net.ipv4.tcp_wmem)
        IFS=' ' read -r a b c <<< "$current"
        net_positive_integer "${a:-}" && net_positive_integer "${b:-}" && net_positive_integer "${c:-}" || return 1
        if (( c < target )); then desired="$a $b $target"
        elif (( c > target )); then net_log "$key 已高于建议上限，保留 $c"; fi ;;
    esac
    printf '%s\t%s\n' "$key" "$current" >> "$previous_file" || return 1
    printf '%s\t%s\n' "$key" "$desired" >> "$desired_file" || return 1
  done
  [[ -s "$desired_file" ]]
}

net_require_root() {
  [[ ${EUID:-$(id -u)} -eq 0 ]] || { net_warn '此操作需要 root；请使用 sudo'; return 1; }
}

net_lock() {
  command -v flock >/dev/null 2>&1 || { net_warn '缺少 flock，请安装 util-linux'; return 1; }
  [[ ! -L "$SNELL_NET_STATE_DIR" ]] || { net_warn '状态目录不能是符号链接'; return 1; }
  install -d -m 0700 "$SNELL_NET_STATE_DIR" || return 1
  [[ ! -L "$SNELL_NET_STATE_DIR/lock" ]] || return 1
  exec 9>"$SNELL_NET_STATE_DIR/lock" || return 1
  flock -n 9 || { net_warn '另一个网络优化/回滚任务正在运行'; return 1; }
}

net_safe_config() {
  [[ ! -L "$SNELL_NET_CONFIG" && ( ! -e "$SNELL_NET_CONFIG" || -f "$SNELL_NET_CONFIG" ) ]] || {
    net_warn "拒绝覆盖非普通文件：$SNELL_NET_CONFIG"; return 1;
  }
}

net_snapshot_config() {
  local dir=$1
  net_safe_config || return 1
  if [[ -f "$SNELL_NET_CONFIG" ]]; then
    cp -p -- "$SNELL_NET_CONFIG" "$dir/config" || return 1
    printf 'present\n' > "$dir/config-state"
  else
    printf 'absent\n' > "$dir/config-state"
  fi
}

net_atomic_config_copy() {
  local source=$1 temp
  net_safe_config || return 1
  temp=$(mktemp "${SNELL_NET_CONFIG}.tmp.XXXXXX") || return 1
  if ! cp -p -- "$source" "$temp" || ! mv -f -- "$temp" "$SNELL_NET_CONFIG"; then
    rm -f -- "$temp"
    return 1
  fi
}

net_restore() {
  local dir=$1 key value actual failed=0 config_state
  [[ -f "$dir/values" && -f "$dir/config-state" ]] || { net_warn "备份不完整：$dir"; return 1; }
  read -r config_state < "$dir/config-state"
  case "$config_state" in
    present) net_atomic_config_copy "$dir/config" || failed=1 ;;
    absent) net_safe_config && rm -f -- "$SNELL_NET_CONFIG" || failed=1 ;;
    *) net_warn '备份中的配置状态无效'; failed=1 ;;
  esac
  while IFS=$'\t' read -r key value; do
    net_supported_key "$key" && [[ -n "$value" && "$value" != *$'\n'* ]] || { failed=1; continue; }
    actual=$(net_read "$key") || actual=''
    [[ "$actual" != "$value" ]] || continue
    if ! net_write "$key" "$value"; then
      net_warn "恢复失败：$key"; failed=1; continue
    fi
    actual=$(net_read "$key") || actual=''
    if [[ "$actual" != "$value" ]]; then net_warn "恢复校验失败：$key"; failed=1; fi
  done < "$dir/values"
  [[ "$failed" -eq 0 ]]
}

net_clear_pending() {
  # Delete only our enumerated transaction files, never an arbitrary directory tree.
  rm -f -- "$SNELL_NET_STATE_DIR/pending/values" "$SNELL_NET_STATE_DIR/pending/desired" "$SNELL_NET_STATE_DIR/pending/config" "$SNELL_NET_STATE_DIR/pending/config-state" "$SNELL_NET_STATE_DIR/pending/generated"
  rmdir -- "$SNELL_NET_STATE_DIR/pending"
}

net_clear_preparing() {
  local dir=$1
  [[ "$dir" == "$SNELL_NET_STATE_DIR/preparing."* && ! -L "$dir" ]] || return 1
  rm -f -- "$dir/values" "$dir/desired" "$dir/config" "$dir/config-state"
  rmdir -- "$dir"
}

net_abort() {
  if [[ "$SNELL_NET_PENDING" -eq 1 ]]; then
    # Commit may already have moved/removed the directory just before a signal.
    [[ -d "$SNELL_NET_STATE_DIR/pending" ]] || { SNELL_NET_PENDING=0; return 0; }
    net_warn '正在恢复本次操作前的参数……'
    if net_restore "$SNELL_NET_STATE_DIR/pending"; then
      net_clear_pending || return 1
      SNELL_NET_PENDING=0
      net_warn '本次变更已回滚'
    else
      net_warn "自动回滚未完全成功，备份保留在 $SNELL_NET_STATE_DIR/pending；请运行 snell-net rollback 重试"
      return 1
    fi
  fi
}

net_recover_pending() {
  if [[ -e "$SNELL_NET_STATE_DIR/pending" ]]; then
    net_warn '发现未完成事务，先恢复该事务之前的状态'
    [[ -d "$SNELL_NET_STATE_DIR/pending" && ! -L "$SNELL_NET_STATE_DIR/pending" ]] || return 1
    SNELL_NET_PENDING=1
    net_abort || return 1
  fi
}

net_apply() {
  local transaction staging key desired actual config_dir
  net_require_root || return 1
  [[ "$(uname -s)" == Linux ]] || { net_warn '仅支持 Linux'; return 1; }
  net_detect_environment
  if [[ "$SNELL_NET_CAN_APPLY" -ne 1 ]]; then
    net_log "SKIPPED：${SNELL_NET_ENVIRONMENT}；${SNELL_NET_REASON}。Snell 安装可继续。"
    return 0
  fi
  net_detect_memory || { net_warn '无法确定有效内存，停止优化'; return 1; }
  net_lock || return 1
  net_recover_pending || return 1
  net_safe_config || return 1
  config_dir=${SNELL_NET_CONFIG%/*}
  [[ -d "$config_dir" ]] || { net_warn "配置目录不存在：$config_dir"; return 1; }
  # A pre-existing baseline is kept intact across all later successful applies.
  [[ ! -L "$SNELL_NET_STATE_DIR/baseline" ]] || return 1
  if [[ -e "$SNELL_NET_STATE_DIR/baseline" && ( ! -f "$SNELL_NET_STATE_DIR/baseline/values" || ! -f "$SNELL_NET_STATE_DIR/baseline/config-state" ) ]]; then
    net_warn '首次备份不完整，停止覆盖'; return 1
  fi
  transaction="$SNELL_NET_STATE_DIR/pending"
  staging=$(mktemp -d "$SNELL_NET_STATE_DIR/preparing.XXXXXX") || return 1
  if ! net_snapshot_config "$staging" || ! net_plan "$staging/desired" "$staging/values"; then
    net_warn '建立优化计划失败，未修改 sysctl'
    net_clear_preparing "$staging" || true
    return 1
  fi
  # An interrupted preparation is harmless; only complete snapshots become pending.
  mv -- "$staging" "$transaction" || { net_clear_preparing "$staging" || true; return 1; }
  SNELL_NET_PENDING=1
  while IFS=$'\t' read -r key desired; do
    actual=$(net_read "$key") || actual=''
    if [[ "$actual" != "$desired" ]]; then
      net_log "${key}：$actual → $desired"
      if ! net_write "$key" "$desired"; then
        net_warn "写入失败：$key"
        net_abort || true
        return 1
      fi
    fi
    actual=$(net_read "$key") || actual=''
    if [[ "$actual" != "$desired" ]]; then
      net_warn "读回校验失败：$key"
      net_abort || true
      return 1
    fi
  done < "$transaction/desired"
  {
    printf '%s\n' "$SNELL_NET_MARKER"
    printf '# Memory-based defaults; existing larger buffers are preserved.\n'
    while IFS=$'\t' read -r key desired; do printf '%s = %s\n' "$key" "$desired"; done < "$transaction/desired"
  } > "$transaction/generated" || { net_abort || true; return 1; }
  chmod 0644 "$transaction/generated" || { net_abort || true; return 1; }
  if ! cmp -s "$transaction/generated" "$SNELL_NET_CONFIG"; then
    net_atomic_config_copy "$transaction/generated" || { net_abort || true; return 1; }
  fi
  if [[ ! -e "$SNELL_NET_STATE_DIR/baseline" ]]; then
    mv -- "$transaction" "$SNELL_NET_STATE_DIR/baseline" || { net_abort || true; return 1; }
  else
    net_clear_pending || { net_warn '参数已生效，但事务文件清理失败'; return 1; }
  fi
  SNELL_NET_PENDING=0
  net_log "已逐项写入并校验，持久配置：$SNELL_NET_CONFIG"
  net_log '新的默认队列不替换网卡正在使用的队列；已有连接可能继续使用原拥塞算法。'
  net_log '不修改路由、MTU、DNS、IPv6、SSH、防火墙或内核；不重启。回滚命令：snell-net rollback'
  net_log '这是按资源与内核能力选择的保守参数，不代表实测最优；需要客户端到 VPS 双向测试才能判断收益。'
}

net_rollback() {
  local archive
  net_require_root || return 1
  net_detect_environment
  if [[ "$SNELL_NET_CAN_APPLY" -ne 1 ]]; then
    net_warn "无法安全执行回滚：${SNELL_NET_REASON}；备份未修改"
    return 1
  fi
  net_lock || return 1
  net_recover_pending || return 1
  if [[ ! -d "$SNELL_NET_STATE_DIR/baseline" || -L "$SNELL_NET_STATE_DIR/baseline" ]]; then
    net_log '没有首次优化备份；没有执行参数恢复'
    return 0
  fi
  if ! net_restore "$SNELL_NET_STATE_DIR/baseline"; then
    net_warn '回滚未完全成功；备份已保留，可修复权限后重新执行 rollback'
    return 1
  fi
  archive=$(mktemp -d "$SNELL_NET_STATE_DIR/restored.XXXXXX") || return 1
  if ! mv -- "$SNELL_NET_STATE_DIR/baseline" "$archive/baseline"; then
    rmdir -- "$archive" || true
    net_warn '参数已恢复，但备份归档失败；原备份仍在'
    return 1
  fi
  net_log "已恢复首次优化前的真实参数与配置文件；备份归档：$archive/baseline"
}

net_status() {
  local key line
  net_log "持久配置：$SNELL_NET_CONFIG"
  if [[ -f "$SNELL_NET_CONFIG" ]]; then
    while IFS= read -r line; do printf '  %s\n' "$line"; done < "$SNELL_NET_CONFIG"
  else net_log '尚无本脚本的持久配置'; fi
  [[ ! -e "$SNELL_NET_STATE_DIR/pending" ]] || net_warn '有未完成事务，运行 snell-net rollback 可尝试恢复'
  if [[ -d "$SNELL_NET_STATE_DIR/baseline" ]]; then net_log '首次参数备份存在，可执行 rollback'
  else net_log '未保存首次参数备份'; fi
  net_log '当前实时值：'
  for key in net.ipv4.tcp_congestion_control net.core.default_qdisc net.ipv4.tcp_mtu_probing net.ipv4.tcp_moderate_rcvbuf net.core.rmem_max net.core.wmem_max net.ipv4.tcp_rmem net.ipv4.tcp_wmem; do net_show_value "$key"; done
  net_log '当前真实网卡队列：'
  if command -v tc >/dev/null 2>&1; then tc qdisc show 2>/dev/null || true; fi
}

net_help() {
  printf '%s\n' \
    '用法：snell-net diagnose [--probe IP] | apply | rollback | status | help' \
    '  diagnose  只读检测系统、权限、内存、路由、MTU、实际队列及 TCP 参数' \
    '  --probe   可选发送 4 个 ICMP 包；不会据此自动调参' \
    '  apply     按内存和内核能力应用保守参数；失败自动恢复本次变更' \
    '  rollback  恢复首次成功优化前的真实参数及本脚本管理的配置文件' \
    '  status    对照持久配置、当前参数和实际网卡队列' \
    '保留更大的现有缓冲上限及已有 BBR/BBR2/BBR3、fq/fq_codel/cake。' \
    '容器、权限不确定时跳过优化；不安装内核、不测速开放端口、不重启。'
}

net_main() {
  local action=${1:-diagnose} probe=''
  [[ $# -eq 0 ]] || shift
  if [[ "$action" == diagnose && $# -eq 2 && "$1" == --probe ]]; then probe=$2; shift 2; fi
  [[ $# -eq 0 ]] || { net_help; return 2; }
  case "$action" in
    diagnose) net_diagnose "$probe" ;;
    apply) net_apply ;;
    rollback) net_rollback ;;
    status) net_status ;;
    help|-h|--help) net_help ;;
    *) net_help; return 2 ;;
  esac
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  set -uo pipefail
  umask 077
  trap 'net_abort || true' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  net_main "$@"
fi
SNELL_AUTO_NETWORK_PAYLOAD_END
}

write_security() {
  cat <<'SNELL_AUTO_SECURITY_PAYLOAD_END'
#!/usr/bin/env bash
# Conservative host hardening for snell-auto. Safe to source for offline tests.

SNELL_SECURITY_STATE=${SNELL_SECURITY_STATE:-/var/lib/snell-security}
SNELL_SECURITY_SYSCTL=${SNELL_SECURITY_SYSCTL:-/etc/sysctl.d/zzzz-snell-auto-security.conf}
SNELL_SECURITY_SSH=${SNELL_SECURITY_SSH:-/etc/ssh/sshd_config.d/00-snell-auto-security.conf}
SNELL_SECURITY_JAIL=${SNELL_SECURITY_JAIL:-/etc/fail2ban/jail.d/snell-auto-sshd.local}
SNELL_SECURITY_APT_PERIODIC=${SNELL_SECURITY_APT_PERIODIC:-/etc/apt/apt.conf.d/99snell-auto-periodic}
SNELL_SECURITY_APT_REBOOT=${SNELL_SECURITY_APT_REBOOT:-/etc/apt/apt.conf.d/99zz-snell-auto-no-reboot}
SNELL_SECURITY_PROC=${SNELL_SECURITY_PROC:-/proc}
SNELL_SECURITY_MARKER='# Managed by snell-security; rollback with snell-security rollback.'
SNELL_SECURITY_TRANSACTION=''
SNELL_SECURITY_NO_PACKAGES=0
SNELL_SECURITY_MASKED=0
SNELL_SECURITY_SSHD=''
SNELL_SECURITY_SSH_UNIT=''
SNELL_SECURITY_CLIENT=''
SNELL_SECURITY_PORTS=''
SNELL_SECURITY_CONTEXT=''
SNELL_SECURITY_REPORT=''

sec_log() { printf '[snell-security] %s\n' "$*"; [[ -z "$SNELL_SECURITY_REPORT" ]] || printf '%s\n' "$*" >> "$SNELL_SECURITY_REPORT"; }
sec_warn() { printf '[snell-security] %s\n' "$*" >&2; [[ -z "$SNELL_SECURITY_REPORT" ]] || printf '%s\n' "$*" >> "$SNELL_SECURITY_REPORT"; }
sec_keys() {
  printf '%s\n' fs.protected_hardlinks fs.protected_symlinks fs.protected_fifos fs.protected_regular kernel.kptr_restrict kernel.dmesg_restrict net.ipv4.tcp_syncookies
}
sec_target() {
  case "$1" in
    sysctl) printf '%s\n' "$SNELL_SECURITY_SYSCTL" ;;
    ssh) printf '%s\n' "$SNELL_SECURITY_SSH" ;;
    jail) printf '%s\n' "$SNELL_SECURITY_JAIL" ;;
    periodic) printf '%s\n' "$SNELL_SECURITY_APT_PERIODIC" ;;
    reboot) printf '%s\n' "$SNELL_SECURITY_APT_REBOOT" ;;
    *) return 1 ;;
  esac
}
sec_owned() { [[ -f "$1" && ! -L "$1" ]] && { grep -Fqx "$SNELL_SECURITY_MARKER" "$1" || grep -Fqx "// ${SNELL_SECURITY_MARKER#\# }" "$1"; }; }
sec_file_id() {
  local id
  for id in sysctl ssh jail periodic reboot; do [[ "$(sec_target "$id")" != "$1" ]] || { printf '%s\n' "$id"; return 0; }; done
  return 1
}
sec_fingerprint() {
  [[ ! -L "$1" ]] || return 1
  if [[ ! -e "$1" ]]; then printf 'absent\n'; return 0; fi
  [[ -f "$1" ]] || return 1
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | awk '{print $1}'
  elif command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | awk '{print $1}'
  else return 1; fi
}
sec_metadata() {
  local target=$1 value=$2 temporary
  mkdir -p "$(dirname "$target")" || return 1
  temporary=$(mktemp "${target}.tmp.XXXXXX") || return 1
  printf '%s\n' "$value" > "$temporary" && chmod 600 "$temporary" && mv -f "$temporary" "$target" || { rm -f "$temporary"; return 1; }
}
sec_matches_expected() {
  local id=$1 current expected
  current=$(sec_fingerprint "$(sec_target "$id")") || return 1
  if [[ -f "$SNELL_SECURITY_STATE/expected.$id" ]]; then
    read -r expected < "$SNELL_SECURITY_STATE/expected.$id" || return 1
    [[ "$current" == "$expected" ]]
  else [[ "$current" == absent ]]; fi
}
sec_can_write() {
  local id
  id=$(sec_file_id "$1") || return 1
  [[ ! -L "$1" ]] && { [[ ! -e "$1" ]] || sec_owned "$1"; } && sec_matches_expected "$id"
}
sec_write_file() {
  local target=$1 input=$2 temporary marker=$SNELL_SECURITY_MARKER id fingerprint
  sec_can_write "$target" || { sec_warn "拒绝覆盖非本脚本管理文件：$target"; return 1; }
  mkdir -p "$(dirname "$target")" || return 1
  temporary=$(mktemp "${target}.tmp.XXXXXX") || return 1
  if [[ "$target" == "$SNELL_SECURITY_APT_PERIODIC" || "$target" == "$SNELL_SECURITY_APT_REBOOT" ]]; then marker="// ${SNELL_SECURITY_MARKER#\# }"; fi
  if ! { printf '%s\n' "$marker"; cat "$input"; } > "$temporary" || ! chmod 644 "$temporary"; then
    rm -f "$temporary"; return 1
  fi
  id=$(sec_file_id "$target") && fingerprint=$(sec_fingerprint "$temporary") || { rm -f "$temporary"; return 1; }
  # Persist expected content before rename, so a kill -9 between rename and ledger
  # update can be recovered without mistaking our own write for a user's edit.
  if [[ -n "$SNELL_SECURITY_TRANSACTION" ]]; then sec_metadata "$SNELL_SECURITY_TRANSACTION/planned.$id" "$fingerprint" || { rm -f "$temporary"; return 1; }; fi
  mv -f "$temporary" "$target" && sec_metadata "$SNELL_SECURITY_STATE/expected.$id" "$fingerprint"
}
sec_snapshot() {
  local directory=$1 id target value key unit enabled active
  mkdir -p "$directory/files" || return 1
  chmod 700 "$directory" "$directory/files" || return 1
  for id in sysctl ssh jail periodic reboot; do
    target=$(sec_target "$id") || return 1
    if [[ -e "$target" || -L "$target" ]]; then
      [[ -f "$target" && ! -L "$target" ]] || return 1
      cp -p "$target" "$directory/files/$id" || return 1
      printf 'present\n' > "$directory/$id.state" || return 1
    else printf 'absent\n' > "$directory/$id.state" || return 1; fi
  done
  : > "$directory/values" || return 1
  while IFS= read -r key; do
    value=$(sysctl -n "$key" 2>/dev/null) || continue
    [[ "$value" =~ ^[0-9]+$ ]] || continue
    printf '%s\t%s\n' "$key" "$value" >> "$directory/values" || return 1
  done < <(sec_keys)
  : > "$directory/services" || return 1
  for unit in fail2ban.service apt-daily.timer apt-daily-upgrade.timer; do
    enabled=$(systemctl is-enabled "$unit" 2>/dev/null) || true
    active=$(systemctl is-active "$unit" 2>/dev/null) || true
    printf '%s\t%s\t%s\n' "$unit" "${enabled:-not-found}" "${active:-inactive}" >> "$directory/services" || return 1
  done
}
sec_restore_file() {
  local directory=$1 id=$2 target state temporary current planned='' original=absent
  target=$(sec_target "$id") || return 1
  [[ -r "$directory/$id.state" ]] || return 1
  read -r state < "$directory/$id.state" || return 1
  current=$(sec_fingerprint "$target") || return 1
  if [[ "$state" == present ]]; then original=$(sec_fingerprint "$directory/files/$id") || return 1; fi
  [[ ! -f "$directory/planned.$id" ]] || read -r planned < "$directory/planned.$id"
  if ! sec_matches_expected "$id" && [[ "$current" != "$planned" && "$current" != "$original" ]]; then
    sec_warn "恢复已跳过：$target 内容校验不匹配，保留用户后续修改"; return 1
  fi
  if [[ -e "$target" || -L "$target" ]]; then
    if ! sec_owned "$target"; then
      if [[ "$state" == present ]] && cmp -s "$target" "$directory/files/$id"; then return 0; fi
      sec_warn "恢复已跳过：$target 已由其他程序修改或不属于本脚本"; return 1
    fi
  fi
  if [[ "$state" == present ]]; then
    mkdir -p "$(dirname "$target")" || return 1
    temporary=$(mktemp "${target}.restore.XXXXXX") || return 1
    cp -p "$directory/files/$id" "$temporary" && mv -f "$temporary" "$target" || { rm -f "$temporary"; return 1; }
  elif [[ "$state" == absent ]]; then
    [[ ! -e "$target" ]] || rm -f "$target" || return 1
  else return 1; fi
  sec_metadata "$SNELL_SECURITY_STATE/expected.$id" "$original"
}
sec_restore_services() {
  local directory=$1 unit enabled active result=0
  while IFS=$'\t' read -r unit enabled active; do
    case "$unit" in fail2ban.service|apt-daily.timer|apt-daily-upgrade.timer) ;; *) return 1;; esac
    if [[ "$unit" == fail2ban.service ]]; then [[ -e "$directory/touched.fail2ban" ]] || continue
    else [[ -e "$directory/touched.updates" ]] || continue; fi
    # A package may remain installed; restore only its prior runtime/enable state.
    case "$enabled" in
      enabled) systemctl enable "$unit" >/dev/null 2>&1 || result=1 ;;
      enabled-runtime)
        systemctl disable "$unit" >/dev/null 2>&1 || result=1
        systemctl enable --runtime "$unit" >/dev/null 2>&1 || result=1
        ;;
      disabled|not-found|'')
        if systemctl is-enabled "$unit" 2>/dev/null | grep -Eq '^enabled(-runtime)?$'; then
          systemctl disable "$unit" >/dev/null 2>&1 || result=1
          if systemctl is-enabled "$unit" 2>/dev/null | grep -Eq '^enabled(-runtime)?$'; then result=1; fi
        fi
        ;;
      masked|masked-runtime|static|indirect|generated|alias|linked|linked-runtime) ;;
      *) sec_warn "未知原始服务状态 $unit=${enabled}；未修改启用状态" ;;
    esac
    if [[ "$active" == active ]]; then
      if [[ "$unit" == fail2ban.service ]] && systemctl is-active --quiet "$unit"; then
        systemctl reload "$unit" >/dev/null 2>&1 || result=1
      elif ! systemctl is-active --quiet "$unit"; then systemctl start "$unit" >/dev/null 2>&1 || result=1; fi
    elif systemctl is-active --quiet "$unit"; then systemctl stop "$unit" >/dev/null 2>&1 || result=1; fi
  done < "$directory/services"
  return "$result"
}
sec_restore_allowed() {
  local directory=$1 id=$2 target state current original=absent planned=''
  target=$(sec_target "$id") && read -r state < "$directory/$id.state" || return 1
  current=$(sec_fingerprint "$target") || return 1
  if [[ "$state" == present ]]; then original=$(sec_fingerprint "$directory/files/$id") || return 1; fi
  [[ ! -f "$directory/planned.$id" ]] || read -r planned < "$directory/planned.$id"
  if ! sec_matches_expected "$id" && [[ "$current" != "$original" && "$current" != "$planned" ]]; then
    sec_warn "恢复冲突：$target 内容已变更；保留文件及运行状态"; return 1
  fi
  [[ "$current" == absent || "$current" == "$original" ]] || sec_owned "$target"
}
sec_restore() {
  local directory=$1 id key value result=0 kernel_ok=1 ssh_ok=1
  [[ -d "$directory/files" && -f "$directory/values" && -f "$directory/services" ]] || return 1
  # Preflight all targets before touching runtime state. If a user has edited a
  # managed file, a partial rollback must not pair it with older running values.
  for id in sysctl ssh jail periodic reboot; do
    [[ ! -e "$directory/touched.$id" ]] || sec_restore_allowed "$directory" "$id" || return 1
  done
  # Stop our newly started Fail2ban before removing its safe jail/ignoreip.
  if [[ -e "$directory/touched.fail2ban" ]] && ! awk -F '\t' '$1=="fail2ban.service" && $3=="active" {found=1} END {exit !found}' "$directory/services"; then
    sec_stop_fail2ban || return 1
  fi
  for id in sysctl ssh jail periodic reboot; do
    if [[ -e "$directory/touched.$id" ]] && ! sec_restore_file "$directory" "$id"; then
      result=1
      [[ "$id" != sysctl ]] || kernel_ok=0
      [[ "$id" != ssh ]] || ssh_ok=0
    fi
  done
  if [[ -e "$directory/touched.sysctl" && "$kernel_ok" == 1 ]]; then
    while IFS=$'\t' read -r key value; do
      sec_keys | grep -Fqx "$key" || { result=1; continue; }
      [[ "$value" =~ ^[0-9]+$ ]] || { result=1; continue; }
      [[ "$(sysctl -n "$key" 2>/dev/null)" == "$value" ]] || sysctl -q -w "$key=$value" >/dev/null 2>&1 || result=1
    done < "$directory/values"
  fi
  sec_find_sshd
  if [[ -e "$directory/touched.ssh" && "$ssh_ok" == 1 && -n "$SNELL_SECURITY_SSHD" && -n "$SNELL_SECURITY_SSH_UNIT" ]]; then
    "$SNELL_SECURITY_SSHD" -t && systemctl reload "$SNELL_SECURITY_SSH_UNIT" || result=1
  fi
  sec_restore_services "$directory" || result=1
  return "$result"
}
sec_package() {
  local package=$1
  if (( SNELL_SECURITY_NO_PACKAGES )); then sec_warn "--no-packages：不安装 $package"; return 1; fi
  if command -v apt-get >/dev/null 2>&1; then
    DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=60 -o Acquire::Retries=1 -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 update &&
      DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=60 -o Dpkg::Options::=--force-confold install -y --no-install-recommends "$package"
  elif command -v dnf >/dev/null 2>&1; then dnf -y --setopt=timeout=20 --setopt=retries=1 install "$package"
  elif command -v yum >/dev/null 2>&1; then yum -y --setopt=timeout=20 --setopt=retries=1 install "$package"
  else sec_warn '没有支持的软件包管理器'; return 1; fi
}
sec_kernel_safe() {
  local result mapping caps
  [[ ! -e /.dockerenv && ! -e /run/.containerenv && ! -s /run/systemd/container ]] || return 1
  command -v systemd-detect-virt >/dev/null 2>&1 || return 1
  systemd-detect-virt --container >/dev/null 2>&1; result=$?
  [[ "$result" -eq 1 ]] || return 1
  mapping=$(awk 'NF==3 {print $1 " " $2 " " $3}' "$SNELL_SECURITY_PROC/self/uid_map" 2>/dev/null)
  [[ "$mapping" == '0 0 4294967295' ]] || return 1
  caps=$(awk '/^CapEff:/ {print $2}' "$SNELL_SECURITY_PROC/self/status" 2>/dev/null)
  [[ "$caps" =~ ^[0-9a-fA-F]{1,16}$ ]] || return 1
  # CAP_SYS_ADMIN and CAP_NET_ADMIN: fail closed in restricted namespaces.
  (( (16#$caps & 2097152) != 0 && (16#$caps & 4096) != 0 ))
}
sec_sysctl() {
  local directory=$1 key current target result=0
  if ! sec_kernel_safe; then sec_warn '内核加固 skipped：容器或内核管理权限不明确'; return 0; fi
  : > "$directory/kernel-plan" || return 1
  while IFS= read -r key; do
    current=$(sysctl -n "$key" 2>/dev/null) || continue
    [[ "$current" =~ ^[0-9]+$ ]] || continue
    if [[ -f "$SNELL_SECURITY_STATE/baseline/values" ]] && ! awk -F '\t' -v wanted="$key" '$1==wanted {found=1} END {exit !found}' "$SNELL_SECURITY_STATE/baseline/values"; then continue; fi
    target=1
    case "$key" in fs.protected_fifos|fs.protected_regular|kernel.kptr_restrict) target=2;; esac
    (( current > target )) && target=$current
    printf '%s = %s\n' "$key" "$target" >> "$directory/kernel-plan" || return 1
  done < <(sec_keys)
  [[ -s "$directory/kernel-plan" ]] || { sec_warn '内核加固 skipped：没有可管理参数'; return 0; }
  : > "$directory/touched.sysctl" || return 1
  sec_write_file "$SNELL_SECURITY_SYSCTL" "$directory/kernel-plan" || return 1
  while read -r key _ target; do
    if ! sysctl -q -w "$key=$target" >/dev/null 2>&1 || [[ "$(sysctl -n "$key" 2>/dev/null)" != "$target" ]]; then result=1; break; fi
  done < "$directory/kernel-plan"
  if (( result )); then
    sec_restore_file "$directory" sysctl || return 1
    while IFS=$'\t' read -r key current; do sysctl -q -w "$key=$current" >/dev/null 2>&1 || return 1; done < "$directory/values"
    sec_warn '内核加固 skipped：写入/验证失败，已恢复本次参数'; return 0
  fi
  sec_log '内核加固已验证：链接/临时文件保护、内核信息访问限制、SYN cookies；保留已有更严格值'
}
sec_valid_ip() {
  local ip=$1 part
  if command -v python3 >/dev/null 2>&1; then
    python3 -c 'import ipaddress,sys; ipaddress.ip_address(sys.argv[1])' "$ip" >/dev/null 2>&1; return
  fi
  [[ "$ip" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
  local IFS=.
  for part in $ip; do [[ ${#part} -le 3 ]] && (( 10#$part <= 255 )) || return 1; done
}
sec_valid_port() { [[ "$1" =~ ^[0-9]{1,5}$ ]] && (( 10#$1 >= 1 && 10#$1 <= 65535 )); }
sec_find_sshd() {
  local unit
  SNELL_SECURITY_SSHD=$(command -v sshd 2>/dev/null || true)
  [[ -n "$SNELL_SECURITY_SSHD" ]] || { [[ ! -x /usr/sbin/sshd ]] || SNELL_SECURITY_SSHD=/usr/sbin/sshd; }
  SNELL_SECURITY_SSH_UNIT=''
  for unit in ssh.service sshd.service; do
    if systemctl is-active --quiet "$unit"; then SNELL_SECURITY_SSH_UNIT=$unit; break; fi
  done
}
sec_ssh_default_service() {
  local command_line pid running
  [[ -n "$SNELL_SECURITY_SSH_UNIT" ]] || return 1
  command_line=$(systemctl show "$SNELL_SECURITY_SSH_UNIT" -p ExecStart --value 2>/dev/null) || return 1
  [[ -n "$command_line" ]] || return 1
  # systemd renders argv and environment variable references; unresolved arguments
  # cannot be safely interpreted as the same /etc/ssh/sshd_config checked below.
  [[ "$command_line" == *"path=$SNELL_SECURITY_SSHD ;"* ]] || return 1
  if [[ "$command_line" =~ (^|[[:space:]])-[fo] ]]; then return 1; fi
  pid=$(systemctl show "$SNELL_SECURITY_SSH_UNIT" -p MainPID --value 2>/dev/null) || return 1
  [[ "$pid" =~ ^[0-9]+$ && "$pid" -gt 1 && -r "$SNELL_SECURITY_PROC/$pid/cmdline" ]] || return 1
  running=$(tr '\0' ' ' < "$SNELL_SECURITY_PROC/$pid/cmdline") || return 1
  # Debian/Ubuntu default units include $SSHD_OPTS. Validate the actually expanded
  # listener argv instead of rejecting every default unit with that placeholder.
  [[ "$running" == *"$SNELL_SECURITY_SSHD"* ]] || return 1
  [[ ! "$running" =~ (^|[[:space:]])-[fo] ]]
}
sec_connection() {
  local source source_port local_ip local_port extra user
  SNELL_SECURITY_CLIENT=''; SNELL_SECURITY_CONTEXT=''
  [[ -n "${SSH_CONNECTION:-}" ]] || return 1
  read -r source source_port local_ip local_port extra <<< "$SSH_CONNECTION"
  [[ -z "$extra" ]] && sec_valid_ip "$source" && sec_valid_ip "$local_ip" && sec_valid_port "$source_port" && sec_valid_port "$local_port" || return 1
  user=${SUDO_USER:-root}
  [[ "$user" =~ ^[a-zA-Z0-9_.@-]+$ ]] || return 1
  SNELL_SECURITY_CLIENT=$source
  SNELL_SECURITY_CONTEXT="user=$user,addr=$source,laddr=$local_ip,lport=$local_port"
}
sec_ssh_auth_view() {
  # Compare every effective value other than the four intentionally hardened keys.
  awk '$1!="permitemptypasswords" && $1!="x11forwarding" && $1!="logingracetime" && $1!="loglevel"' "$1" | LC_ALL=C sort
}
sec_ssh_value() { awk -v key="$2" '$1==key {print $2; exit}' "$1"; }
sec_ssh_targets_ok() {
  local before=$1 after=$2 old_time time old_log log
  [[ "$(sec_ssh_value "$after" permitemptypasswords)" == no && "$(sec_ssh_value "$after" x11forwarding)" == no ]] || return 1
  old_time=$(sec_ssh_value "$before" logingracetime); time=$(sec_ssh_value "$after" logingracetime)
  [[ "$old_time" =~ ^[0-9]+$ && "$time" =~ ^[0-9]+$ ]] || return 1
  (( time > 0 && time <= 120 )) || return 1
  (( old_time == 0 || time <= old_time )) || return 1
  old_log=$(sec_ssh_value "$before" loglevel); log=$(sec_ssh_value "$after" loglevel)
  case "$old_log" in DEBUG*) [[ "$log" == "$old_log" ]] ;; *) [[ "$log" == VERBOSE || "$log" == DEBUG* ]] ;; esac
}
sec_ssh_restore_reload() {
  sec_restore_file "$1" ssh && "$SNELL_SECURITY_SSHD" -t && systemctl reload "$SNELL_SECURITY_SSH_UNIT"
}
sec_ssh() {
  local directory=$1 grace log result=0 context=0
  sec_find_sshd
  if [[ -z "$SNELL_SECURITY_SSHD" || -z "$SNELL_SECURITY_SSH_UNIT" ]]; then sec_warn 'SSH 加固 skipped：未发现活动 ssh/sshd 服务'; return 0; fi
  if ! sec_ssh_default_service; then sec_warn 'SSH 加固 skipped：服务启动参数不是可验证的默认配置，可能使用自定义 -f/-o/环境参数'; return 0; fi
  if ! "$SNELL_SECURITY_SSHD" -t || ! "$SNELL_SECURITY_SSHD" -T > "$directory/ssh-before"; then sec_warn 'SSH 加固 skipped：现有配置校验失败'; return 0; fi
  if [[ -n "${SSH_CONNECTION:-}" ]]; then
    if ! sec_connection || ! "$SNELL_SECURITY_SSHD" -T -C "$SNELL_SECURITY_CONTEXT" > "$directory/ssh-context-before"; then
      sec_warn 'SSH 加固 skipped：无法验证当前 SSH 会话上下文'; return 0
    fi
    context=1
  fi
  grace=$(sec_ssh_value "$directory/ssh-before" logingracetime)
  [[ "$grace" =~ ^[0-9]+$ ]] || { sec_warn 'SSH 加固 skipped：LoginGraceTime 无法解析'; return 0; }
  (( grace > 0 && grace < 120 )) || grace=120
  log=$(sec_ssh_value "$directory/ssh-before" loglevel)
  case "$log" in DEBUG*) ;; *) log=VERBOSE;; esac
  printf 'PermitEmptyPasswords no\nX11Forwarding no\nLoginGraceTime %s\nLogLevel %s\n' "$grace" "$log" > "$directory/ssh-plan" || return 1
  : > "$directory/touched.ssh" || return 1
  sec_write_file "$SNELL_SECURITY_SSH" "$directory/ssh-plan" || return 1
  "$SNELL_SECURITY_SSHD" -t && "$SNELL_SECURITY_SSHD" -T > "$directory/ssh-after" || result=1
  if (( result == 0 )); then
    cmp -s <(sec_ssh_auth_view "$directory/ssh-before") <(sec_ssh_auth_view "$directory/ssh-after") && sec_ssh_targets_ok "$directory/ssh-before" "$directory/ssh-after" || result=1
  fi
  if (( context && result == 0 )); then
    "$SNELL_SECURITY_SSHD" -T -C "$SNELL_SECURITY_CONTEXT" > "$directory/ssh-context-after" &&
      cmp -s <(sec_ssh_auth_view "$directory/ssh-context-before") <(sec_ssh_auth_view "$directory/ssh-context-after") &&
      sec_ssh_targets_ok "$directory/ssh-context-before" "$directory/ssh-context-after" || result=1
  fi
  if (( result )); then
    sec_restore_file "$directory" ssh || return 1
    sec_warn 'SSH 加固 skipped：Include 未生效、Match 覆盖或认证/转发设置变化；已还原文件，未 reload'; return 0
  fi
  if ! systemctl reload "$SNELL_SECURITY_SSH_UNIT" || ! systemctl is-active --quiet "$SNELL_SECURITY_SSH_UNIT"; then
    sec_ssh_restore_reload "$directory" || { sec_warn 'SSH reload 和恢复校验失败，请检查现有 SSH 服务'; return 1; }
    sec_warn 'SSH 加固 skipped：reload 失败，已恢复'; return 0
  fi
  sec_log 'SSH 加固生效；已验证认证方式、端口及转发不变，只执行 reload'
}
sec_collect_ports() {
  local directory=$1 port line listener source sport local_ip local_port extra
  SNELL_SECURITY_PORTS=''
  [[ -n "$SNELL_SECURITY_SSHD" ]] || return 1
  "$SNELL_SECURITY_SSHD" -T > "$directory/ssh-ports" || return 1
  : > "$directory/ports" || return 1
  while read -r port; do
    sec_valid_port "$port" || return 1
    printf '%s\n' "$((10#$port))" >> "$directory/ports"
  done < <(awk '$1=="port" {print $2}' "$directory/ssh-ports")
  command -v ss >/dev/null 2>&1 || return 1
  ss -H -lntp > "$directory/listeners" 2>/dev/null || return 1
  while read -r line; do
    [[ "$line" == *'"sshd"'* || "$line" == *'"sshd-session"'* ]] || continue
    listener=$(awk '{print $4}' <<< "$line"); port=${listener##*:}
    sec_valid_port "$port" || return 1
    printf '%s\n' "$((10#$port))" >> "$directory/ports"
  done < "$directory/listeners"
  read -r source sport local_ip local_port extra <<< "$SSH_CONNECTION"
  sec_valid_port "$local_port" || return 1
  printf '%s\n' "$((10#$local_port))" >> "$directory/ports"
  SNELL_SECURITY_PORTS=$(LC_ALL=C sort -nu "$directory/ports" | paste -sd, -)
  [[ -n "$SNELL_SECURITY_PORTS" ]]
}
sec_unmask_install() {
  if (( SNELL_SECURITY_MASKED )); then
    systemctl unmask --runtime fail2ban.service >/dev/null 2>&1 || return 1
    SNELL_SECURITY_MASKED=0
    [[ -z "$SNELL_SECURITY_TRANSACTION" ]] || rm -f "$SNELL_SECURITY_TRANSACTION/mask-owned" || return 1
  fi
}
sec_journal_backend() { command -v python3 >/dev/null 2>&1 && python3 -c 'from systemd import journal' >/dev/null 2>&1; }
sec_install_fail2ban_packages() {
  (( SNELL_SECURITY_NO_PACKAGES == 0 )) || return 1
  sec_package fail2ban || return 1
  if ! sec_journal_backend; then
    sec_package python3-systemd || sec_warn '现有软件源未能安装 python3-systemd；稍后按后端实际可用性决定是否启用'
  fi
}
sec_stop_fail2ban() {
  if systemctl is-active --quiet fail2ban.service; then
    systemctl stop fail2ban.service >/dev/null 2>&1 || { sec_warn 'Fail2ban 无法停止，保留 jail 与白名单'; return 1; }
    if systemctl is-active --quiet fail2ban.service; then sec_warn 'Fail2ban 仍在运行，保留 jail 与白名单'; return 1; fi
  fi
}
sec_fail2ban() {
  local directory=$1 action='' enabled
  if systemctl is-active --quiet fail2ban.service; then sec_log 'Fail2ban 已运行：保留现有配置与封禁规则，不接管'; return 0; fi
  if command -v fail2ban-client >/dev/null 2>&1 && ! sec_owned "$SNELL_SECURITY_JAIL"; then sec_log 'Fail2ban 已安装：保留现有配置，不自动启动或接管'; return 0; fi
  sec_find_sshd
  if ! sec_ssh_default_service || ! sec_connection || ! sec_collect_ports "$directory"; then
    sec_warn 'Fail2ban skipped：无法可靠验证当前 SSH 来源/全部监听端口；请从 SSH 会话运行'; return 0
  fi
  if ! command -v fail2ban-client >/dev/null 2>&1; then
    (( SNELL_SECURITY_NO_PACKAGES == 0 )) || { sec_warn 'Fail2ban skipped：--no-packages 且未安装'; return 0; }
    enabled=$(systemctl is-enabled fail2ban.service 2>/dev/null || true)
    case "$enabled" in masked*) sec_warn 'Fail2ban skipped：服务已被管理员 mask'; return 0;; esac
    : > "$directory/touched.fail2ban" || return 1
    : > "$directory/mask-owned" || return 1
    SNELL_SECURITY_MASKED=1
    if ! systemctl mask --runtime fail2ban.service >/dev/null 2>&1; then sec_unmask_install || return 1; sec_warn 'Fail2ban skipped：无法阻止包安装时自动启动'; return 0; fi
    enabled=$(systemctl is-enabled fail2ban.service 2>/dev/null || true)
    if [[ "$enabled" != masked-runtime && "$enabled" != masked ]]; then
      sec_unmask_install || return 1
      sec_warn 'Fail2ban skipped：临时 mask 未实际生效，未安装包'; return 0
    fi
    if ! sec_install_fail2ban_packages; then sec_unmask_install && sec_restore_services "$directory" || return 1; sec_warn 'Fail2ban skipped：现有软件源安装失败'; return 0; fi
    sec_unmask_install || return 1
  fi
  if ! sec_journal_backend; then
    sec_restore_services "$directory" || return 1
    sec_warn 'Fail2ban skipped：缺少 systemd journal Python 后端'; return 0
  fi
  if command -v nft >/dev/null 2>&1 && [[ -f /etc/fail2ban/action.d/nftables-multiport.conf ]] && nft list ruleset >/dev/null 2>&1; then action=nftables-multiport
  elif command -v iptables >/dev/null 2>&1 && [[ -f /etc/fail2ban/action.d/iptables-multiport.conf ]] && iptables -L -n >/dev/null 2>&1; then
    if ! command -v ip6tables >/dev/null 2>&1 || ! ip6tables -L -n >/dev/null 2>&1; then
      sec_restore_services "$directory" || return 1
      sec_warn 'Fail2ban skipped：IPv6 防护 action 不可用'; return 0
    fi
    action=iptables-multiport
  else sec_restore_services "$directory" || return 1; sec_warn 'Fail2ban skipped：没有可验证的 nftables/iptables action'; return 0; fi
  printf '[sshd]\nenabled = false\n\n[snell-auto-sshd]\nenabled = true\nfilter = sshd\nbackend = systemd\nport = %s\nprotocol = tcp\nbanaction = %s\nmaxretry = 8\nfindtime = 10m\nbantime = 15m\nusedns = no\nignoreip = 127.0.0.0/8 ::1 %s\n' "$SNELL_SECURITY_PORTS" "$action" "$SNELL_SECURITY_CLIENT" > "$directory/jail-plan" || return 1
  : > "$directory/touched.jail" || return 1
  : > "$directory/touched.fail2ban" || return 1
  sec_write_file "$SNELL_SECURITY_JAIL" "$directory/jail-plan" || return 1
  if ! fail2ban-client -t > "$directory/fail2ban-test" 2>&1 || ! fail2ban-client -d > "$directory/fail2ban-plan" 2>&1; then
    sec_restore_file "$directory" jail || return 1
    sec_restore_services "$directory" || return 1
    sec_warn 'Fail2ban skipped：jail 配置验证失败，已恢复文件'; return 0
  fi
  # Do not activate any unrelated jail left by a package or administrator.
  if ! command -v python3 >/dev/null 2>&1 || ! python3 - "$directory/fail2ban-plan" "$SNELL_SECURITY_CLIENT" <<'PY'
import ast, sys
jails, ignored = [], []
for line in open(sys.argv[1]):
    try:
        cmd = ast.literal_eval(line.strip())
    except (ValueError, SyntaxError):
        continue
    if not isinstance(cmd, (list, tuple)):
        continue
    if len(cmd) >= 2 and cmd[0] == 'add':
        jails.append(cmd[1])
    if len(cmd) >= 4 and cmd[:3] == ['set', 'snell-auto-sshd', 'addignoreip']:
        ignored.extend(cmd[3:])
sys.exit(0 if jails == ['snell-auto-sshd'] and sys.argv[2] in ignored else 1)
PY
  then
    sec_restore_file "$directory" jail || return 1
    sec_restore_services "$directory" || return 1
    sec_warn 'Fail2ban skipped：发现其他启用 jail 或来源白名单未确认；未启动服务'; return 0
  fi
  if ! systemctl enable --now fail2ban.service || ! sec_fail2ban_ready; then
    sec_stop_fail2ban || return 1
    sec_restore_file "$directory" jail && sec_restore_services "$directory" || return 1
    sec_warn 'Fail2ban skipped：启动/验证失败，已恢复'; return 0
  fi
  sec_log "Fail2ban 已启用：TCP ${SNELL_SECURITY_PORTS}；10 分钟失败 8 次封禁 15 分钟；当前 SSH 来源已加入白名单"
}
sec_fail2ban_ready() {
  local attempt
  for attempt in 1 2 3 4 5; do
    if systemctl is-active --quiet fail2ban.service && fail2ban-client status snell-auto-sshd >/dev/null 2>&1; then return 0; fi
    [[ "$attempt" == 5 ]] || sleep 1
  done
  return 1
}
sec_apt_read() {
  local value
  value=$(apt-config shell SNELL_APT_VALUE "$1" 2>/dev/null) || return 1
  # apt-config's quoted numeric/boolean output only; never eval configuration.
  printf '%s\n' "$value" | sed -n "s/^SNELL_APT_VALUE='\([^']*\)'$/\1/p"
}
sec_updates() {
  local directory=$1 distro current key result=0 policy=0
  distro=$(awk -F= '$1=="ID" {gsub(/"/, "", $2); print $2; exit}' /etc/os-release 2>/dev/null)
  if [[ "$distro" != debian && "$distro" != ubuntu ]] || ! command -v apt-config >/dev/null 2>&1; then
    sec_warn '自动安全更新 skipped：仅自动配置 Debian/Ubuntu；其他系统保留原策略'; return 0
  fi
  for key in APT::Periodic::Enable APT::Periodic::Update-Package-Lists APT::Periodic::Unattended-Upgrade; do
    current=$(sec_apt_read "$key") || { sec_warn '自动安全更新 skipped：无法读取现有 APT 策略'; return 0; }
    if [[ "$current" == 0 || "$current" == false ]]; then
      sec_warn "自动安全更新 skipped：管理员已有禁用策略 $key=$current"; return 0
    fi
  done
  # Installing this package can create distro-owned 20auto-upgrades or trigger
  # post-install policy outside our rollback scope. Manage only an existing install.
  command -v unattended-upgrade >/dev/null 2>&1 || { sec_warn '自动安全更新 skipped：尚未安装 unattended-upgrades；包安装会创建额外系统策略，请由管理员单独安装'; return 0; }
  apt-config dump > "$directory/apt-effective" || return 1
  # Package defaults supply distro security origins; do not invent or replace origins.
  if ! grep -Eq 'Unattended-Upgrade::(Allowed-Origins|Origins-Pattern)::.*(security|Security)' "$directory/apt-effective"; then
    sec_warn '自动安全更新 skipped：未发现安全更新来源，保留现有源与策略'; return 0
  fi
  : > "$directory/periodic-plan" || return 1
  for key in APT::Periodic::Update-Package-Lists APT::Periodic::Unattended-Upgrade; do
    current=$(sec_apt_read "$key") || return 1
    if [[ -z "$current" ]]; then
      printf '%s "1";\n' "$key" >> "$directory/periodic-plan" || return 1
    elif sec_owned "$SNELL_SECURITY_APT_PERIODIC"; then
      # Effective value may originate from our previous apply. Keep our setting
      # instead of deleting it and accidentally disabling scheduling on reruns.
      awk -v key="$key" '$1==key {print}' "$SNELL_SECURITY_APT_PERIODIC" >> "$directory/periodic-plan" || return 1
    fi
  done
  printf 'Unattended-Upgrade::Automatic-Reboot "false";\n' > "$directory/reboot-plan" || return 1
  : > "$directory/touched.updates" || return 1
  : > "$directory/touched.periodic" || return 1
  : > "$directory/touched.reboot" || return 1
  sec_write_file "$SNELL_SECURITY_APT_PERIODIC" "$directory/periodic-plan" && sec_write_file "$SNELL_SECURITY_APT_REBOOT" "$directory/reboot-plan" || return 1
  [[ "$(sec_apt_read Unattended-Upgrade::Automatic-Reboot)" == false ]] || result=1
  for key in APT::Periodic::Update-Package-Lists APT::Periodic::Unattended-Upgrade; do
    current=$(sec_apt_read "$key")
    [[ -n "$current" && "$current" != 0 && "$current" != false ]] || result=1
  done
  if (( result )); then
    sec_restore_file "$directory" periodic && sec_restore_file "$directory" reboot || return 1
    sec_warn '自动安全更新 skipped：有效配置校验失败，已恢复'; return 0
  fi
  # Timers schedule future work; no upgrade or apt-daily service is run here.
  for key in apt-daily.timer apt-daily-upgrade.timer; do
    current=$(systemctl is-enabled "$key" 2>/dev/null || true)
    case "$current" in masked*) sec_warn "保留管理员 mask：$key"; continue;; esac
    if ! systemctl enable "$key" >/dev/null 2>&1; then sec_warn "$key 无法启用；请检查系统更新定时器"; policy=1; fi
  done
  sec_log 'APT 自动更新沿用现有 Allowed-Origins/Origins-Pattern（可能不限于安全更新）、排除/周期；禁止自动重启，未运行升级任务'
  sec_log '已有活动更新 timer 保持运行；新启用的非活动 timer 下次开机开始调度'
  (( policy == 0 )) || sec_warn '自动更新调度未完全启用，请查看 status'
}
sec_firewall() {
  sec_log '防火墙审计（仅查看，不启用/重置或改变默认策略）：'
  if command -v ufw >/dev/null 2>&1; then ufw status 2>/dev/null || true; fi
  if command -v firewall-cmd >/dev/null 2>&1; then firewall-cmd --state 2>/dev/null || true; fi
  if command -v nft >/dev/null 2>&1; then
    if nft list tables 2>/dev/null; then :; else sec_warn 'nftables 状态不可读'; fi
  fi
  if command -v iptables >/dev/null 2>&1; then iptables -S INPUT 2>/dev/null || true; fi
  if command -v ss >/dev/null 2>&1; then sec_log '当前 TCP 监听端口：'; ss -H -lnt 2>/dev/null || true; fi
}
sec_status() {
  local key value
  [[ ! -d "$SNELL_SECURITY_STATE/baseline" ]] || sec_log "首次基线备份：$SNELL_SECURITY_STATE/baseline"
  for key in sysctl ssh jail periodic reboot; do
    value=$(sec_target "$key")
    if sec_owned "$value"; then sec_log "${key}：本脚本管理 ($value)"; else sec_log "${key}：未管理"; fi
  done
  sec_log '实际内核参数：'
  while IFS= read -r key; do value=$(sysctl -n "$key" 2>/dev/null) || value=unsupported; printf '  %s = %s\n' "$key" "$value"; done < <(sec_keys)
  for key in fail2ban.service apt-daily.timer apt-daily-upgrade.timer; do
    value=$(systemctl is-active "$key" 2>/dev/null || true); sec_log "${key}：active=${value:-unknown}, enabled=$(systemctl is-enabled "$key" 2>/dev/null || true)"
  done
  if [[ -f "$SNELL_SECURITY_STATE/latest" ]]; then
    read -r value < "$SNELL_SECURITY_STATE/latest"
    if [[ "$value" == "$SNELL_SECURITY_STATE/transaction."* && -f "$value/report" ]]; then sec_log '最近一次执行报告：'; cat "$value/report"; fi
  fi
  [[ ! -f "$SNELL_SECURITY_STATE/pending" ]] || sec_warn '检测到未完成事务；下次 apply/rollback 将先尝试恢复'
  sec_firewall
}
sec_recover_pending() {
  local directory suffix
  [[ -f "$SNELL_SECURITY_STATE/pending" ]] || return 0
  read -r directory < "$SNELL_SECURITY_STATE/pending" || return 1
  suffix=${directory#"$SNELL_SECURITY_STATE/transaction."}
  [[ "$directory" == "$SNELL_SECURITY_STATE/transaction."* && "$suffix" =~ ^[a-zA-Z0-9]+$ && -d "$directory" && ! -L "$directory" ]] || { sec_warn 'pending 事务路径无效，停止以保护现有配置'; return 1; }
  sec_warn "恢复上次未完成事务：$directory"
  if [[ -f "$directory/mask-owned" ]]; then
    SNELL_SECURITY_MASKED=1
    sec_unmask_install || return 1
  fi
  sec_restore "$directory" || return 1
  rm -f "$SNELL_SECURITY_STATE/pending" || return 1
}
sec_abort() {
  local result=$?
  trap - EXIT INT TERM
  sec_unmask_install || result=1
  if [[ -n "$SNELL_SECURITY_TRANSACTION" && -d "$SNELL_SECURITY_TRANSACTION" ]]; then
    sec_warn '操作未完成，正在恢复本次变更'
    if sec_restore "$SNELL_SECURITY_TRANSACTION"; then rm -f "$SNELL_SECURITY_STATE/pending" || result=1
    else sec_warn "自动恢复有未完成项，保留备份：$SNELL_SECURITY_TRANSACTION"; result=1; fi
  fi
  exit "$result"
}
sec_apply() {
  local id target directory baseline_new=0
  for id in sysctl ssh jail periodic reboot; do
    target=$(sec_target "$id")
    sec_can_write "$target" || { sec_warn "拒绝覆盖未标记文件：$target"; return 1; }
  done
  [[ ! -L "$SNELL_SECURITY_STATE" ]] || return 1
  mkdir -p "$SNELL_SECURITY_STATE" || return 1
  chmod 700 "$SNELL_SECURITY_STATE" || return 1
  directory=$(mktemp -d "$SNELL_SECURITY_STATE/transaction.XXXXXX") || return 1
  sec_snapshot "$directory" || return 1
  SNELL_SECURITY_TRANSACTION=$directory
  SNELL_SECURITY_REPORT="$directory/report"
  sec_metadata "$SNELL_SECURITY_STATE/pending" "$directory" || return 1
  if [[ ! -d "$SNELL_SECURITY_STATE/baseline" ]]; then baseline_new=1; fi
  sec_sysctl "$directory" && sec_ssh "$directory" && sec_fail2ban "$directory" && sec_updates "$directory" || return 1
  if (( baseline_new )); then
    target=$(mktemp -d "$SNELL_SECURITY_STATE/baseline-new.XXXXXX") || return 1
    cp -a "$directory/." "$target/" && mv "$target" "$SNELL_SECURITY_STATE/baseline" || return 1
  else
    for id in sysctl ssh jail periodic reboot fail2ban updates; do
      [[ ! -e "$directory/touched.$id" ]] || : > "$SNELL_SECURITY_STATE/baseline/touched.$id" || return 1
    done
  fi
  SNELL_SECURITY_TRANSACTION=''
  rm -f "$SNELL_SECURITY_STATE/pending" || return 1
  printf '%s\n' "$directory" > "$SNELL_SECURITY_STATE/latest" || return 1
  sec_firewall
  sec_log '基础加固流程完成；skipped 项未启用。rollback 恢复首次基线，不卸载新装软件包，也无法撤销已发生的软件更新。'
}
sec_require_host() {
  [[ "$EUID" -eq 0 ]] || { sec_warn '请使用 root 或 sudo'; return 1; }
  [[ "$(uname -s)" == Linux && -d /run/systemd/system ]] || { sec_warn '需要 Linux + systemd'; return 1; }
  local command
  for command in systemctl sysctl flock awk sed grep sort cmp mktemp; do command -v "$command" >/dev/null 2>&1 || { sec_warn "缺少依赖：$command"; return 1; }; done
}
sec_help() {
  printf '%s\n' '用法：snell-security apply [--no-packages] | status | rollback | help' \
    'apply：可回滚的内核/SSH 基础加固，条件允许时配置 Fail2ban 和 Debian/Ubuntu 自动安全更新。' \
    '--no-packages：只使用已安装组件，不访问软件源。' \
    'status：只读审计。rollback：恢复第一次成功 apply 前的文件、参数及服务状态。' \
    '不修改 SSH 端口/密码登录/root 登录，不启用全局防火墙，不重启 VPS。'
}
sec_main() {
  local action=${1:-apply}
  [[ $# -eq 0 ]] || shift
  case "$action" in help|-h|--help) [[ $# -eq 0 ]] || return 2; sec_help; return 0;; apply|status|rollback) ;; *) sec_warn "未知命令：$action"; sec_help; return 2;; esac
  if [[ "$action" == apply && $# -eq 1 && "$1" == --no-packages ]]; then SNELL_SECURITY_NO_PACKAGES=1; shift; fi
  [[ $# -eq 0 ]] || { sec_warn '参数错误'; return 2; }
  sec_require_host || return 1
  if [[ "$action" == status ]]; then sec_status; return; fi
  [[ ! -L "$SNELL_SECURITY_STATE" ]] || return 1
  mkdir -p "$SNELL_SECURITY_STATE" && chmod 700 "$SNELL_SECURITY_STATE" || return 1
  exec 9> "$SNELL_SECURITY_STATE/lock" || return 1
  flock -n 9 || { sec_warn '另一个安全管理任务正在运行'; return 1; }
  sec_recover_pending || return 1
  trap sec_abort EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  case "$action" in
    apply) sec_apply ;;
    status) sec_status ;;
    rollback)
      [[ -d "$SNELL_SECURITY_STATE/baseline" ]] || { sec_warn '没有可回滚的首次基线'; return 1; }
      if sec_restore "$SNELL_SECURITY_STATE/baseline"; then
        mv "$SNELL_SECURITY_STATE/baseline" "$SNELL_SECURITY_STATE/restored-$(date +%Y%m%d%H%M%S)" || return 1
        sec_log '已恢复首次基线；已安装软件包及已执行的软件更新保留'
      else sec_warn '部分回滚失败，保留基线以便排查'; return 1; fi
      ;;
  esac
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  set -uo pipefail
  sec_main "$@"
fi
SNELL_AUTO_SECURITY_PAYLOAD_END
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then auto_main "$@"; fi
